class ScopedMetricTimer {
public:
  explicit ScopedMetricTimer(std::string_view metric) noexcept
      : metric_(metric), enabled_(metrics::enabled()) {
    if (enabled_)
      start_ = Clock::now();
  }

  ~ScopedMetricTimer() {
    if (!enabled_)
      return;
    const auto elapsed = std::chrono::duration_cast<std::chrono::microseconds>(
        Clock::now() - start_);
    metrics::count(metric_, static_cast<uint64_t>(std::max<int64_t>(
                                elapsed.count(), int64_t{0})));
  }

private:
  using Clock = std::chrono::steady_clock;
  std::string_view metric_;
  bool enabled_ = false;
  Clock::time_point start_{};
};

// A clean final frame must not erase an intermittent capture failure from a
// checkpoint run. Retain the live gauge and accumulate observations under the
// same key in the separate counters namespace. Counts are face occurrences,
// not unique faces. A failing observation also records its guest frame so the
// next bounded capture can target the actual fault.
void recordValidationCount(std::string_view metric, uint32_t value,
                           uint64_t frame) {
  metrics::setState(metric, value);
  if (value == 0u || !metrics::enabled())
    return;
  metrics::count(metric, value);
  metrics::setState(std::string(metric) + ".last_failure_frame",
                    static_cast<int64_t>(frame));
  metrics::traceAtFrame("renderer.crash3.validation_failure", frame,
                        {{std::string(metric), value}});
}

