// A camera-anchored Crash scenery resource is an ordering-table background,
// not a nearby occluder in the modern D32 scene.  The largest binary32 value
// below 2^32 maps to nextafter(1, 0) under the replay shader's shared 2^-32
// projective-W normalization.  Do not use 2^32 itself: that maps to the 1.0
// clear sentinel, making a real sky surface indistinguishable from an empty
// pixel to F8 and to the temporal disocclusion resolver.  The original
// homogeneous W remains untouched for coverage and interpolation.
constexpr uint32_t kCrash3BackgroundDepthBits =
    games::crash3::CAMERA_BACKGROUND_DEPTH_BITS;
static_assert(std::bit_cast<float>(kCrash3BackgroundDepthBits) <
              std::bit_cast<float>(UINT32_C(0x4f800000)));
static_assert(std::bit_cast<float>(kCrash3BackgroundDepthBits) *
                  replay::vulkan_abi::PROJECTIVE_W_TO_DEPTH_SCALE <
              VULKAN_REPLAY_SEED_DEPTH_CLEAR);
constexpr replay::vulkan_abi::PresentationDepthPushConstants
    kCrash3BackgroundDepthClass{0u, kCrash3BackgroundDepthBits, 0u,
                                kCrash3BackgroundDepthBits};
// Crash's resident renderer inserts primitives at
//   1904 - ((ZSF3/4 * sum(SZ)) >> 15)
// in its local 2048-entry OT.  The shared presentation coordinate assigns 32
// units to one OT cell and keeps an 8192-unit near guard.  Away from the
// intentional endpoint clamp this reduces exactly to one continuous affine
// family: 4 * camera-Z + 12800.  Keeping the affine common to the complete
// resident topology avoids packet/triangle seams while placing scenery in the
// same apparent-depth domain as dynamically scaled objects.
constexpr float kCrash3ResidentDepthMultiplier = 4.0f;
constexpr float kCrash3ResidentDepthBias = 12800.0f;
constexpr replay::vulkan_abi::PresentationDepthPushConstants
    kCrash3ResidentDepthClass{
        std::bit_cast<uint32_t>(kCrash3ResidentDepthMultiplier),
        std::bit_cast<uint32_t>(kCrash3ResidentDepthBias),
        std::bit_cast<uint32_t>(kCrash3ResidentDepthMultiplier),
        std::bit_cast<uint32_t>(kCrash3ResidentDepthBias)};

uint64_t hashCrash3PresentationDrawState(
    const replay::vulkan_abi::DrawUniforms &uniforms,
    const replay::vulkan_abi::PresentationDepthPushConstants &depth) noexcept {
  uint64_t hash = UINT64_C(1469598103934665603);
  const auto mix = [&hash](uint32_t word) {
    for (uint32_t shift = 0u; shift < 32u; shift += 8u) {
      hash ^= static_cast<uint8_t>(word >> shift);
      hash *= UINT64_C(1099511628211);
    }
  };
  const auto mixFloats = [&](const auto &values) {
    for (const float value : values)
      mix(std::bit_cast<uint32_t>(value));
  };
  const auto mixWords = [&](const auto &values) {
    for (const uint32_t value : values)
      mix(value);
  };
  mixFloats(uniforms.positionScaleBias);
  mixFloats(uniforms.depthScaleBias);
  mixFloats(uniforms.uvDomain);
  mixWords(uniforms.textureState);
  mixWords(uniforms.textureWindow);
  mixWords(uniforms.destinationState);
  mix(depth.occlusionMultiplierBits);
  mix(depth.occlusionBiasBits);
  mix(depth.surfaceMultiplierBits);
  mix(depth.surfaceBiasBits);
  return hash;
}

uint64_t hashCrash3PresentationGroup(uint64_t state, bool first, bool second,
                                     bool third) noexcept {
  state ^= static_cast<uint64_t>(first) << 1u;
  state ^= static_cast<uint64_t>(second) << 2u;
  state ^= static_cast<uint64_t>(third) << 3u;
  return state;
}
