bool validDisplayScanoutPlan(const DisplayScanoutPlan &plan) noexcept {
  const bool formatValid = plan.format == DisplayScanoutFormat::RGB555 ||
                           plan.format == DisplayScanoutFormat::PackedRGB888;
  const bool sourcePhaseValid =
      plan.format == DisplayScanoutFormat::PackedRGB888 ||
      (plan.sourceByteX & 1u) == 0;
  const bool fieldValid = plan.field == DisplayScanoutField::NotApplicable ||
                          plan.field == DisplayScanoutField::Unknown ||
                          plan.field == DisplayScanoutField::Even ||
                          plan.field == DisplayScanoutField::Odd;
  return formatValid && sourcePhaseValid && fieldValid &&
         plan.sourceByteX < GPU::VRAM_WIDTH * 2u &&
         plan.sourceY < GPU::VRAM_HEIGHT && plan.rowStep != 0 &&
         plan.rowStep <= GPU::VRAM_HEIGHT &&
         plan.destinationOrigin.x <= plan.canvas.width &&
         plan.destinationOrigin.y <= plan.canvas.height &&
         plan.activeExtent.width <=
             plan.canvas.width - plan.destinationOrigin.x &&
         plan.activeExtent.height <=
             plan.canvas.height - plan.destinationOrigin.y;
}

bool displayScanoutHasActiveImage(const DisplayScanoutPlan &plan) noexcept {
  return plan.enabled && plan.activeExtent.width != 0 &&
         plan.activeExtent.height != 0;
}

bool displayScanoutSupportsPrecisionAtlas(
    const DisplayScanoutPlan &plan) noexcept {
  return plan.progressive && plan.field == DisplayScanoutField::NotApplicable &&
         plan.rowStep == 1 && plan.format == DisplayScanoutFormat::RGB555 &&
         (plan.sourceByteX & 1u) == 0;
}

bool diagnosticApertureCoversScanout(const DisplayScanoutPlan &plan) noexcept {
  if (!displayScanoutHasActiveImage(plan) ||
      plan.format != DisplayScanoutFormat::RGB555 ||
      (plan.sourceByteX & 1u) != 0)
    return false;
  const uint64_t sourceWordX = plan.sourceByteX / sizeof(Color16);
  const uint64_t finalSourceY =
      static_cast<uint64_t>(plan.sourceY) +
      static_cast<uint64_t>(plan.activeExtent.height - 1u) * plan.rowStep;
  return sourceWordX + plan.activeExtent.width <= GPU::VRAM_WIDTH &&
         finalSourceY < GPU::VRAM_HEIGHT;
}

DisplayAperture
diagnosticApertureForScanout(const DisplayScanoutPlan &plan) noexcept {
  DisplayAperture aperture;
  aperture.x = std::min(plan.sourceByteX / 2u, GPU::VRAM_WIDTH - 1u);
  aperture.y = std::min(plan.sourceY, GPU::VRAM_HEIGHT - 1u);
  aperture.width =
      std::clamp(plan.activeExtent.width, 1u, GPU::VRAM_WIDTH - aperture.x);
  aperture.height =
      std::clamp(plan.activeExtent.height, 1u, GPU::VRAM_HEIGHT - aperture.y);
  aperture.enabled = displayScanoutHasActiveImage(plan);
  return aperture;
}

DisplayScanoutPlan conservativeInterlaceScanoutPlan(
    const DisplayScanoutPlan &programmed) noexcept {
  DisplayScanoutPlan plan = programmed;
  // Preserve the complete canvas, placement, byte phase and format even
  // though field parity is unavailable. A contiguous native resolve is an
  // honest complete-image fallback; it must never reinterpret Packed24 as
  // RGB555 or repeat one guessed field through a rowStep=2 wrap.
  plan.rowStep = 1;
  plan.progressive = true;
  plan.field = DisplayScanoutField::NotApplicable;
  return plan;
}

[[noreturn]] void failVulkan(const char *operation, VkResult result) {
  throw std::runtime_error(fmt::format("{} failed with VkResult {}", operation,
                                       static_cast<int>(result)));
}

void requireVulkan(VkResult result, const char *operation) {
  if (result != VK_SUCCESS)
    failVulkan(operation, result);
}

std::vector<uint32_t> readSpirv(const char *name) {
  std::filesystem::path shaderDirectory;
  if (const char *overridePath = std::getenv("PS1RECOMP_VULKAN_SHADER_DIR")) {
    shaderDirectory = overridePath;
  } else if (char *basePath = SDL_GetBasePath()) {
    shaderDirectory = std::filesystem::path(basePath) / "shaders";
    SDL_free(basePath);
  }
  if (shaderDirectory.empty() || !std::filesystem::exists(shaderDirectory))
    shaderDirectory = PS1RECOMP_VULKAN_SHADER_DIR;
  const std::filesystem::path path = shaderDirectory / name;
  std::ifstream stream(path, std::ios::binary | std::ios::ate);
  if (!stream)
    throw std::runtime_error("cannot open Vulkan shader " + path.string());
  const std::streamsize byteCount = stream.tellg();
  if (byteCount <= 0 || (byteCount % 4) != 0)
    throw std::runtime_error("invalid SPIR-V size for " + path.string());
  stream.seekg(0, std::ios::beg);
  std::vector<uint32_t> words(static_cast<std::size_t>(byteCount) / 4u);
  if (!stream.read(reinterpret_cast<char *>(words.data()), byteCount))
    throw std::runtime_error("cannot read Vulkan shader " + path.string());
  return words;
}

uint32_t acceleratedScale(int requested) {
  // Keep accidental configuration values from allocating an unbounded image.
  // 8x still covers research captures while Crash 3 currently targets 4x.
  return static_cast<uint32_t>(std::clamp(requested, 1, 8));
}

replay::ReplayDepthMode
requestedReplayDepthMode(const RendererOptions &options) {
  if (!options.trueDepth)
    return replay::ReplayDepthMode::Off;
  if (options.trueDepthMode == "hybrid")
    return replay::ReplayDepthMode::Hybrid;
  if (options.trueDepthMode == "strict")
    return replay::ReplayDepthMode::Strict;
  throw std::invalid_argument("unknown Vulkan true-depth mode: " +
                              options.trueDepthMode);
}

replay::ReplayPolicyState
requestedReplayPolicy(const RendererOptions &options) {
  return {acceleratedScale(options.internalScale), options.pgxp,
          options.trueColor, requestedReplayDepthMode(options)};
}

bool requestsPrecisionReplay(const RendererOptions &options) {
  return options.internalScale > 1 || options.pgxp || options.trueDepth ||
         options.trueColor;
}

bool supportsFirstLiveGeometryProfile(const RendererOptions &options) {
  // Hybrid and strict share the same tested packet pipelines. The replay
  // baker selects painter-write versus less-equal; disabling strict here
  // silently fell back to native pixels even for fully precise geometry.
  // Other scales and geometric near clipping retain their separate gates.
  return options.internalScale == 4 && options.pgxp && !options.pgxpNearClip &&
         options.trueDepth && (options.trueDepthMode == "hybrid" ||
                               options.trueDepthMode == "strict") &&
         options.trueColor;
}

replay::ReplayCapabilityMask
firstLiveGeometryCapabilities(const RendererOptions &options) {
  replay::ReplayCapabilityMask capabilities =
      replay::replayCapabilityBit(replay::ReplayCapability::FrameLatch);
  if (!supportsFirstLiveGeometryProfile(options))
    return capabilities;

  capabilities |=
      replay::replayCapabilityBit(replay::ReplayCapability::ClearDepth) |
      replay::replayCapabilityBit(replay::ReplayCapability::Reset) |
      replay::replayCapabilityBit(replay::ReplayCapability::NativeTileUpload) |
      replay::replayCapabilityBit(replay::ReplayCapability::PaintPixels) |
      replay::replayCapabilityBit(replay::ReplayCapability::PaintRect) |
      replay::replayCapabilityBit(replay::ReplayCapability::FillRect) |
      replay::replayCapabilityBit(replay::ReplayCapability::CopyRect) |
      replay::replayCapabilityBit(replay::ReplayCapability::CpuUpload) |
      replay::replayCapabilityBit(replay::ReplayCapability::DrawPacket) |
      replay::replayCapabilityBit(replay::ReplayCapability::Projected3D) |
      replay::replayCapabilityBit(replay::ReplayCapability::Screen2D) |
      replay::replayCapabilityBit(replay::ReplayCapability::NearPlaneSaturate) |
      replay::replayCapabilityBit(replay::ReplayCapability::DrawOpaque) |
      replay::replayCapabilityBit(
          replay::ReplayCapability::DrawSemiTransparent) |
      replay::replayCapabilityBit(replay::ReplayCapability::DrawUntextured) |
      replay::replayCapabilityBit(replay::ReplayCapability::DrawTextured) |
      replay::replayCapabilityBit(replay::ReplayCapability::TextureIndexed4) |
      replay::replayCapabilityBit(replay::ReplayCapability::TextureIndexed8) |
      replay::replayCapabilityBit(replay::ReplayCapability::TextureDirect15) |
      replay::replayCapabilityBit(replay::ReplayCapability::ForceMaskWrite) |
      replay::replayCapabilityBit(
          replay::ReplayCapability::DestinationColorFeedback) |
      replay::replayCapabilityBit(
          replay::ReplayCapability::DestinationMaskRead) |
      replay::replayCapabilityBit(
          replay::ReplayCapability::DepthPainterOrdered) |
      replay::replayCapabilityBit(replay::ReplayCapability::DepthPainterWrite) |
      replay::replayCapabilityBit(replay::ReplayCapability::DepthInvalidate) |
      replay::replayCapabilityBit(
          replay::ReplayCapability::DepthTestWriteLessEqual);
  return capabilities;
}

