    VkFramebuffer crash3SemiInterlockFramebuffer = VK_NULL_HANDLE;
    VkPipeline crash3SidecarScenerySemiInterlockPipeline = VK_NULL_HANDLE;
    VkPipeline crash3SidecarRawSemiInterlockPipeline = VK_NULL_HANDLE;
    VkPipeline preciseLessEqualPipeline = VK_NULL_HANDLE;
