  struct ReplayInventory {
    uint64_t nativeTileUploads = 0;
    uint64_t surfaceSeeds = 0;
    uint64_t drawPackets = 0;
    uint64_t projectedDraws = 0;
    uint64_t screen2DDraws = 0;
    uint64_t texturedDraws = 0;
    uint64_t translucentDraws = 0;
    uint64_t checkMaskDraws = 0;
    uint64_t drawVertices = 0;
    uint64_t fillRects = 0;
    uint64_t copyRects = 0;
    uint64_t cpuUploads = 0;
    uint64_t cpuUploadWords = 0;
    uint64_t paintPixels = 0;
    uint64_t paintedPixels = 0;
    uint64_t paintRects = 0;
    uint64_t paintRectCommands = 0;
    uint64_t clearDepths = 0;
    uint64_t resets = 0;
    uint64_t frameLatches = 0;
  };

  static ReplayInventory
  measureReplayInventory(std::span<const replay::CrashReplayFramePtr> frames) {
    ReplayInventory inventory;
    for (const replay::CrashReplayFramePtr &frame : frames) {
      if (!frame)
        continue;
      for (const replay::Operation &operation : frame->operations()) {
        if (std::holds_alternative<replay::NativeTileUpload>(operation)) {
          ++inventory.nativeTileUploads;
        } else if (std::holds_alternative<replay::SurfaceSeed>(operation)) {
          ++inventory.surfaceSeeds;
        } else if (const auto *draw =
                       std::get_if<replay::DrawPacket>(&operation)) {
          ++inventory.drawPackets;
          if (draw->route == replay::PacketRoute::Projected3D)
            ++inventory.projectedDraws;
          else
            ++inventory.screen2DDraws;
          if (draw->textured)
            ++inventory.texturedDraws;
          if (draw->state.blend.enabled)
            ++inventory.translucentDraws;
          if (draw->state.mask.checkMaskBit)
            ++inventory.checkMaskDraws;
          inventory.drawVertices += draw->vertexCount;
        } else if (std::holds_alternative<replay::FillRect>(operation)) {
          ++inventory.fillRects;
        } else if (std::holds_alternative<replay::CopyRect>(operation)) {
          ++inventory.copyRects;
        } else if (const auto *upload =
                       std::get_if<replay::CpuUpload>(&operation)) {
          ++inventory.cpuUploads;
          if (upload->phase == replay::CpuUploadPhase::Data)
            inventory.cpuUploadWords += upload->pixels.size();
        } else if (const auto *paint =
                       std::get_if<replay::PaintPixels>(&operation)) {
          ++inventory.paintPixels;
          inventory.paintedPixels += paint->pixels.size();
        } else if (const auto *paint =
                       std::get_if<replay::PaintRect>(&operation)) {
          ++inventory.paintRects;
          inventory.paintRectCommands += paint->coalescedCommandCount;
        } else if (std::holds_alternative<replay::ClearDepth>(operation)) {
          ++inventory.clearDepths;
        } else if (std::holds_alternative<replay::Reset>(operation)) {
          ++inventory.resets;
        } else if (std::holds_alternative<replay::FrameLatch>(operation)) {
          ++inventory.frameLatches;
        }
      }
    }
    return inventory;
  }

  static void
  publishReplayInventoryNamespace(std::string_view prefix,
                                  const ReplayInventory &inventory) {
    if (!ps1::metrics::enabled())
      return;
    const std::array<std::pair<std::string_view, uint64_t>, 20> counters{{
        {"native_tile_upload", inventory.nativeTileUploads},
        {"surface_seed", inventory.surfaceSeeds},
        {"draw_packet", inventory.drawPackets},
        {"draw_projected", inventory.projectedDraws},
        {"draw_screen_2d", inventory.screen2DDraws},
        {"draw_textured", inventory.texturedDraws},
        {"draw_translucent", inventory.translucentDraws},
        {"draw_check_mask", inventory.checkMaskDraws},
        {"draw_vertices", inventory.drawVertices},
        {"fill_rect", inventory.fillRects},
        {"copy_rect", inventory.copyRects},
        {"cpu_upload", inventory.cpuUploads},
        {"cpu_upload_words", inventory.cpuUploadWords},
        {"paint_pixels", inventory.paintPixels},
        {"painted_pixels", inventory.paintedPixels},
        {"paint_rect", inventory.paintRects},
        {"paint_rect_commands", inventory.paintRectCommands},
        {"clear_depth", inventory.clearDepths},
        {"reset", inventory.resets},
        {"frame_latch", inventory.frameLatches},
    }};
    for (const auto &[suffix, value] : counters)
      ps1::metrics::count(fmt::format("{}{}", prefix, suffix), value);
  }

  static void publishSubmittedReplayInventory(
      std::span<const replay::CrashReplayFramePtr> frames,
      replay::ModernReplaySubmissionRoute route) {
    const ReplayInventory inventory = measureReplayInventory(frames);
    publishReplayInventoryNamespace("host.renderer.replay_ir.", inventory);
    switch (route) {
    case replay::ModernReplaySubmissionRoute::M1Replay:
      publishReplayInventoryNamespace("host.renderer.replay_ir.m1_submitted.",
                                      inventory);
      break;
    case replay::ModernReplaySubmissionRoute::M0Reanchor:
      publishReplayInventoryNamespace(
          "host.renderer.replay_ir.m0_reanchor_submitted.", inventory);
      break;
    case replay::ModernReplaySubmissionRoute::M0PresentOnly:
      break;
    }
  }

  uint32_t findMemoryType(uint32_t typeBits,
                          VkMemoryPropertyFlags properties) const {
    VkPhysicalDeviceMemoryProperties memoryProperties{};
    vkGetPhysicalDeviceMemoryProperties(physicalDevice, &memoryProperties);
    for (uint32_t i = 0; i < memoryProperties.memoryTypeCount; ++i) {
      if ((typeBits & (1u << i)) != 0 &&
          (memoryProperties.memoryTypes[i].propertyFlags & properties) ==
              properties) {
        return i;
      }
    }
    throw std::runtime_error("no compatible Vulkan memory type");
  }

  void createBuffer(VkDeviceSize size, VkBufferUsageFlags usage,
                    VkMemoryPropertyFlags properties, VkBuffer &buffer,
                    VkDeviceMemory &memory) {
    VkBufferCreateInfo bufferInfo{VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO};
    bufferInfo.size = size;
    bufferInfo.usage = usage;
    bufferInfo.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
    requireVulkan(vkCreateBuffer(device, &bufferInfo, nullptr, &buffer),
                  "vkCreateBuffer");
    VkMemoryRequirements requirements{};
    vkGetBufferMemoryRequirements(device, buffer, &requirements);
    VkMemoryAllocateInfo allocation{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};
    allocation.allocationSize = requirements.size;
    allocation.memoryTypeIndex =
        findMemoryType(requirements.memoryTypeBits, properties);
    requireVulkan(vkAllocateMemory(device, &allocation, nullptr, &memory),
                  "vkAllocateMemory(buffer)");
    requireVulkan(vkBindBufferMemory(device, buffer, memory, 0),
                  "vkBindBufferMemory");
  }

  void createImage(uint32_t width, uint32_t height, VkFormat format,
                   VkImageUsageFlags usage, VkImage &image,
                   VkDeviceMemory &memory) {
    VkImage createdImage = VK_NULL_HANDLE;
    VkDeviceMemory allocatedMemory = VK_NULL_HANDLE;
    VkImageCreateInfo imageInfo{VK_STRUCTURE_TYPE_IMAGE_CREATE_INFO};
    imageInfo.imageType = VK_IMAGE_TYPE_2D;
    imageInfo.extent = {width, height, 1};
    imageInfo.mipLevels = 1;
    imageInfo.arrayLayers = 1;
    imageInfo.format = format;
    imageInfo.tiling = VK_IMAGE_TILING_OPTIMAL;
    imageInfo.initialLayout = VK_IMAGE_LAYOUT_UNDEFINED;
    imageInfo.usage = usage;
    imageInfo.samples = VK_SAMPLE_COUNT_1_BIT;
    imageInfo.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
    requireVulkan(vkCreateImage(device, &imageInfo, nullptr, &createdImage),
                  "vkCreateImage");
    try {
      VkMemoryRequirements requirements{};
      vkGetImageMemoryRequirements(device, createdImage, &requirements);
      VkMemoryAllocateInfo allocation{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};
      allocation.allocationSize = requirements.size;
      allocation.memoryTypeIndex = findMemoryType(
          requirements.memoryTypeBits, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
      requireVulkan(
          vkAllocateMemory(device, &allocation, nullptr, &allocatedMemory),
          "vkAllocateMemory(image)");
      requireVulkan(vkBindImageMemory(device, createdImage, allocatedMemory, 0),
                    "vkBindImageMemory");
    } catch (...) {
      if (allocatedMemory != VK_NULL_HANDLE)
        vkFreeMemory(device, allocatedMemory, nullptr);
      vkDestroyImage(device, createdImage, nullptr);
      throw;
    }
    image = createdImage;
    memory = allocatedMemory;
  }

  VkImageView createImageView(
      VkImage image, VkFormat format,
      VkImageAspectFlags aspectMask = VK_IMAGE_ASPECT_COLOR_BIT) const {
    VkImageViewCreateInfo viewInfo{VK_STRUCTURE_TYPE_IMAGE_VIEW_CREATE_INFO};
    viewInfo.image = image;
    viewInfo.viewType = VK_IMAGE_VIEW_TYPE_2D;
    viewInfo.format = format;
    viewInfo.subresourceRange.aspectMask = aspectMask;
    viewInfo.subresourceRange.baseMipLevel = 0;
    viewInfo.subresourceRange.levelCount = 1;
    viewInfo.subresourceRange.baseArrayLayer = 0;
    viewInfo.subresourceRange.layerCount = 1;
    VkImageView view = VK_NULL_HANDLE;
    requireVulkan(vkCreateImageView(device, &viewInfo, nullptr, &view),
                  "vkCreateImageView");
    return view;
  }

  void requireImageSupport(const char *name, VkExtent2D extent, VkFormat format,
                           VkImageUsageFlags usage,
                           VkFormatFeatureFlags requiredFeatures) const {
    if (extent.width == 0 || extent.height == 0) {
      throw std::runtime_error(
          fmt::format("{} has invalid zero Vulkan extent {}x{}", name,
                      extent.width, extent.height));
    }

    VkFormatProperties formatProperties{};
    vkGetPhysicalDeviceFormatProperties(physicalDevice, format,
                                        &formatProperties);
    const VkFormatFeatureFlags available = normalizedOptimalTilingFeatures(
        physicalDevice, formatProperties.optimalTilingFeatures);
    if ((available & requiredFeatures) != requiredFeatures) {
      throw std::runtime_error(
          fmt::format("{} format {} lacks optimal-tiling features 0x{:x}", name,
                      static_cast<int>(format), requiredFeatures));
    }

    VkImageFormatProperties imageProperties{};
    const VkResult imageSupport = vkGetPhysicalDeviceImageFormatProperties(
        physicalDevice, format, VK_IMAGE_TYPE_2D, VK_IMAGE_TILING_OPTIMAL,
        usage, 0, &imageProperties);
    if (imageSupport == VK_ERROR_FORMAT_NOT_SUPPORTED) {
      throw std::runtime_error(
          fmt::format("{} format {} does not support Vulkan usage 0x{:x}", name,
                      static_cast<int>(format), usage));
    }
    requireVulkan(imageSupport, "vkGetPhysicalDeviceImageFormatProperties");
    if (extent.width > imageProperties.maxExtent.width ||
        extent.height > imageProperties.maxExtent.height ||
        (imageProperties.sampleCounts & VK_SAMPLE_COUNT_1_BIT) == 0) {
      throw std::runtime_error(fmt::format(
          "{} extent {}x{} exceeds supported {}x{}", name, extent.width,
          extent.height, imageProperties.maxExtent.width,
          imageProperties.maxExtent.height));
    }

    if ((usage & (VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT |
                  VK_IMAGE_USAGE_DEPTH_STENCIL_ATTACHMENT_BIT)) != 0) {
      VkPhysicalDeviceProperties properties{};
      vkGetPhysicalDeviceProperties(physicalDevice, &properties);
      if (extent.width > properties.limits.maxFramebufferWidth ||
          extent.height > properties.limits.maxFramebufferHeight) {
        throw std::runtime_error(fmt::format(
            "{} extent {}x{} exceeds framebuffer limit {}x{}", name,
            extent.width, extent.height, properties.limits.maxFramebufferWidth,
            properties.limits.maxFramebufferHeight));
      }
    }
  }

  void destroyImageResource(ImageResource &resource) {
    if (device != VK_NULL_HANDLE) {
      if (resource.view != VK_NULL_HANDLE)
        vkDestroyImageView(device, resource.view, nullptr);
      if (resource.image != VK_NULL_HANDLE)
        vkDestroyImage(device, resource.image, nullptr);
      if (resource.memory != VK_NULL_HANDLE)
        vkFreeMemory(device, resource.memory, nullptr);
    }
    resource = {};
  }

  void destroyBufferResource(BufferResource &resource) {
    if (device != VK_NULL_HANDLE) {
      if (resource.mapped != nullptr && resource.memory != VK_NULL_HANDLE)
        vkUnmapMemory(device, resource.memory);
      if (resource.buffer != VK_NULL_HANDLE)
        vkDestroyBuffer(device, resource.buffer, nullptr);
      if (resource.memory != VK_NULL_HANDLE)
        vkFreeMemory(device, resource.memory, nullptr);
    }
    resource = {};
  }

  void destroyDeviceBufferResource(DeviceBufferResource &resource) {
    if (device != VK_NULL_HANDLE) {
      if (resource.buffer != VK_NULL_HANDLE)
        vkDestroyBuffer(device, resource.buffer, nullptr);
      if (resource.memory != VK_NULL_HANDLE)
        vkFreeMemory(device, resource.memory, nullptr);
    }
    resource = {};
  }

  static std::optional<VkDeviceSize>
  alignReadbackOffset(VkDeviceSize value, VkDeviceSize alignment) {
    if (alignment == 0)
      return std::nullopt;
    const VkDeviceSize remainder = value % alignment;
    if (remainder == 0)
      return value;
    const VkDeviceSize addition = alignment - remainder;
    if (addition > std::numeric_limits<VkDeviceSize>::max() - value)
      return std::nullopt;
    return value + addition;
  }

  uint32_t
  findReplayReadbackMemoryType(uint32_t typeBits,
                               VkMemoryPropertyFlags &selectedFlags) const {
    VkPhysicalDeviceMemoryProperties properties{};
    vkGetPhysicalDeviceMemoryProperties(physicalDevice, &properties);
    int bestScore = -1;
    uint32_t bestIndex = 0;
    for (uint32_t index = 0; index < properties.memoryTypeCount; ++index) {
      if ((typeBits & (1u << index)) == 0)
        continue;
      const VkMemoryPropertyFlags flags =
          properties.memoryTypes[index].propertyFlags;
      if ((flags & VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT) == 0)
        continue;
      const int score =
          ((flags & VK_MEMORY_PROPERTY_HOST_CACHED_BIT) != 0 ? 4 : 0) +
          ((flags & VK_MEMORY_PROPERTY_HOST_COHERENT_BIT) != 0 ? 2 : 0);
      if (score > bestScore) {
        bestScore = score;
        bestIndex = index;
        selectedFlags = flags;
      }
    }
    if (bestScore < 0)
      throw std::runtime_error(
          "no host-visible Vulkan memory type for replay readback");
    return bestIndex;
  }

  void destroyReplayDiagnosticReadback(FrameContext &frame) {
    auto &readback = frame.diagnosticReadback;
    if (device != VK_NULL_HANDLE) {
      if (readback.mapped != nullptr && readback.memory != VK_NULL_HANDLE)
        vkUnmapMemory(device, readback.memory);
      if (readback.buffer != VK_NULL_HANDLE)
        vkDestroyBuffer(device, readback.buffer, nullptr);
      if (readback.memory != VK_NULL_HANDLE)
        vkFreeMemory(device, readback.memory, nullptr);
    }
    readback = {};
  }

  void ensureReplayDiagnosticReadback(
      FrameContext &frame, const replay::VulkanReplayDiagnosticRegion &region,
      bool reservePreCorrectionDepth, bool visibilityAudit,
      bool visibilityCandidate, bool visibilityStack, uint32_t frameIndex) {
    auto &readback = frame.diagnosticReadback;
    if (readback.pending)
      throw std::runtime_error(
          "cannot resize a pending Vulkan replay readback");

    const VkDeviceSize scaledWidth =
        static_cast<VkDeviceSize>(region.nativeWidth) * region.internalScale;
    const VkDeviceSize scaledHeight =
        static_cast<VkDeviceSize>(region.nativeHeight) * region.internalScale;
    if (scaledWidth == 0 || scaledHeight == 0 ||
        scaledWidth > replayResources.color.extent.width ||
        scaledHeight > replayResources.color.extent.height ||
        scaledWidth > std::numeric_limits<VkDeviceSize>::max() / scaledHeight)
      throw std::runtime_error("invalid Vulkan replay readback extent");
    const VkDeviceSize pixels = scaledWidth * scaledHeight;
    if (pixels > std::numeric_limits<VkDeviceSize>::max() / sizeof(Color32))
      throw std::runtime_error("Vulkan replay readback size overflow");

    const VkDeviceSize colorBytes = pixels * sizeof(Color32);
    const VkDeviceSize maskBytes = pixels;
    const VkDeviceSize depthBytes = pixels * sizeof(float);
    VkPhysicalDeviceProperties properties{};
    vkGetPhysicalDeviceProperties(physicalDevice, &properties);
    const VkDeviceSize alignment = std::max<VkDeviceSize>(
        sizeof(float), properties.limits.optimalBufferCopyOffsetAlignment);
    const auto maskOffset = alignReadbackOffset(colorBytes, alignment);
    if (!maskOffset.has_value() ||
        maskBytes > std::numeric_limits<VkDeviceSize>::max() - *maskOffset)
      throw std::runtime_error("Vulkan replay mask readback offset overflow");
    const auto depthOffset =
        alignReadbackOffset(*maskOffset + maskBytes, alignment);
    if (!depthOffset.has_value() ||
        depthBytes > std::numeric_limits<VkDeviceSize>::max() - *depthOffset)
      throw std::runtime_error("Vulkan replay depth readback offset overflow");
    VkDeviceSize requiredSize = *depthOffset + depthBytes;
    VkDeviceSize occlusionDepthOffset = 0;
    VkDeviceSize hostSceneDepthOffset = 0;
    const VkDeviceSize hostSceneDepthBytes =
        replayReadbackConfig.rawDepthDump &&
                replayGeometryResources.crash3SceneryOcclusion
            ? depthBytes
            : 0u;
    VkDeviceSize otOwnerOffset = 0;
    VkDeviceSize strictOwnerOffset = 0;
    VkDeviceSize liftedOwnerOffset = 0;
    VkDeviceSize otDepthOffset = 0;
    VkDeviceSize strictDepthOffset = 0;
    VkDeviceSize liftedDepthOffset = 0;
    VkDeviceSize otEvidenceOffset = 0;
    VkDeviceSize strictEvidenceOffset = 0;
    VkDeviceSize liftedEvidenceOffset = 0;
    VkDeviceSize visibilityStackOffset = 0;
    VkDeviceSize scanoutColorOffset = 0;
    VkDeviceSize scanoutColorBytes = 0;
    VkDeviceSize visibilityStackBytes = 0;
    uint32_t visibilityStackRecordCapacity = 0;
    const VkDeviceSize ownerBytes = visibilityAudit ? pixels * 4u : 0u;
    const VkDeviceSize visibilityDepthBytes =
        (reservePreCorrectionDepth || visibilityAudit) ? pixels * sizeof(float)
                                                       : 0u;
    const VkDeviceSize evidenceBytes = visibilityAudit ? pixels : 0u;
    const auto appendPlane = [&](VkDeviceSize bytes, VkDeviceSize &offset,
                                 const char *name) {
      const auto aligned = alignReadbackOffset(requiredSize, alignment);
      if (!aligned.has_value() ||
          bytes > std::numeric_limits<VkDeviceSize>::max() - *aligned) {
        throw std::runtime_error(
            fmt::format("Vulkan replay {} readback overflow", name));
      }
      offset = *aligned;
      requiredSize = offset + bytes;
    };
    appendPlane(depthBytes, occlusionDepthOffset, "occlusion depth");
    if (hostSceneDepthBytes != 0u)
      appendPlane(hostSceneDepthBytes, hostSceneDepthOffset,
                  "host scene depth");
    if (replayReadbackConfig.temporalMidpoint) {
      const VkDeviceSize scanoutPixels =
          static_cast<VkDeviceSize>(scanoutExtent.width) * scanoutExtent.height;
      if (scanoutExtent.width == 0u || scanoutExtent.height == 0u ||
          scanoutPixels >
              std::numeric_limits<VkDeviceSize>::max() / sizeof(Color32)) {
        throw std::runtime_error("invalid Vulkan scanout readback extent");
      }
      scanoutColorBytes = scanoutPixels * sizeof(Color32);
      appendPlane(scanoutColorBytes, scanoutColorOffset, "scanout color");
    }
    if (visibilityAudit) {
      appendPlane(ownerBytes, otOwnerOffset, "OT owner");
      appendPlane(ownerBytes, strictOwnerOffset, "strict owner");
      appendPlane(visibilityDepthBytes, otDepthOffset, "OT depth");
      appendPlane(visibilityDepthBytes, strictDepthOffset, "strict depth");
      appendPlane(evidenceBytes, otEvidenceOffset, "OT evidence");
      appendPlane(evidenceBytes, strictEvidenceOffset, "strict evidence");
      if (visibilityCandidate) {
        appendPlane(ownerBytes, liftedOwnerOffset, "lifted owner");
        appendPlane(visibilityDepthBytes, liftedDepthOffset, "lifted depth");
        appendPlane(evidenceBytes, liftedEvidenceOffset, "lifted evidence");
      }
    } else if (reservePreCorrectionDepth) {
      appendPlane(visibilityDepthBytes, strictDepthOffset,
                  "pre-correction depth");
    }
    if (visibilityStack) {
      if (!visibilityAudit || !replayVisibilityResources.complete() ||
          !replayVisibilityResources.fragmentStack ||
          frameIndex >= replayVisibilityResources.stackDescriptorSets.size()) {
        throw std::runtime_error(
            "Vulkan visibility stack resources are incomplete");
      }
      if (pixels > std::numeric_limits<uint32_t>::max()) {
        throw std::runtime_error(
            "Vulkan visibility stack sample index exceeds uint32");
      }
      constexpr VkDeviceSize headerBytes =
          sizeof(replay::vulkan_abi::VisibilityStackHeader);
      constexpr VkDeviceSize recordBytes =
          sizeof(replay::vulkan_abi::VisibilityStackRecord);
      if (properties.limits.maxStorageBufferRange <= headerBytes) {
        throw std::runtime_error(
            "Vulkan visibility stack exceeds maxStorageBufferRange");
      }
      const uint64_t maximumRecords = std::min<uint64_t>(
          (static_cast<uint64_t>(properties.limits.maxStorageBufferRange) -
           headerBytes) /
              recordBytes,
          std::numeric_limits<uint32_t>::max());
      uint64_t requestedRecords = 0;
      if (replayVisibilityStackRecordCapacity.has_value()) {
        requestedRecords = *replayVisibilityStackRecordCapacity;
        if (requestedRecords > maximumRecords) {
          throw std::runtime_error(fmt::format(
              "PS1_VULKAN_VISIBILITY_STACK_RECORDS={} exceeds this device's "
              "maximum {}",
              requestedRecords, maximumRecords));
        }
      } else {
        const uint64_t sizingHint =
            static_cast<uint64_t>(pixels) >
                    std::numeric_limits<uint64_t>::max() / 4u
                ? std::numeric_limits<uint64_t>::max()
                : static_cast<uint64_t>(pixels) * 4u;
        requestedRecords = std::min(sizingHint, maximumRecords);
      }
      if (requestedRecords == 0)
        throw std::runtime_error("Vulkan visibility stack has zero capacity");
      visibilityStackRecordCapacity = static_cast<uint32_t>(requestedRecords);
      visibilityStackBytes = headerBytes + requestedRecords * recordBytes;
      const VkDeviceSize storageAlignment = std::max<VkDeviceSize>(
          alignof(replay::vulkan_abi::VisibilityStackHeader),
          properties.limits.minStorageBufferOffsetAlignment);
      const auto stackOffset =
          alignReadbackOffset(requiredSize, storageAlignment);
      if (!stackOffset.has_value() ||
          visibilityStackBytes >
              std::numeric_limits<VkDeviceSize>::max() - *stackOffset) {
        throw std::runtime_error(
            "Vulkan visibility stack readback size overflow");
      }
      visibilityStackOffset = *stackOffset;
      requiredSize = visibilityStackOffset + visibilityStackBytes;
    }

    if (readback.buffer == VK_NULL_HANDLE || readback.capacity < requiredSize) {
      destroyReplayDiagnosticReadback(frame);
      auto &candidate = frame.diagnosticReadback;
      VkBufferCreateInfo bufferInfo{VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO};
      bufferInfo.size = requiredSize;
      bufferInfo.usage =
          VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_STORAGE_BUFFER_BIT;
      bufferInfo.sharingMode = VK_SHARING_MODE_EXCLUSIVE;
      try {
        requireVulkan(
            vkCreateBuffer(device, &bufferInfo, nullptr, &candidate.buffer),
            "vkCreateBuffer(replay readback)");
        VkMemoryRequirements requirements{};
        vkGetBufferMemoryRequirements(device, candidate.buffer, &requirements);
        VkMemoryPropertyFlags memoryFlags = 0;
        VkMemoryAllocateInfo allocation{VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO};
        allocation.allocationSize = requirements.size;
        allocation.memoryTypeIndex = findReplayReadbackMemoryType(
            requirements.memoryTypeBits, memoryFlags);
        requireVulkan(
            vkAllocateMemory(device, &allocation, nullptr, &candidate.memory),
            "vkAllocateMemory(replay readback)");
        requireVulkan(
            vkBindBufferMemory(device, candidate.buffer, candidate.memory, 0),
            "vkBindBufferMemory(replay readback)");
        requireVulkan(vkMapMemory(device, candidate.memory, 0, VK_WHOLE_SIZE, 0,
                                  &candidate.mapped),
                      "vkMapMemory(replay readback)");
        candidate.capacity = requiredSize;
        candidate.hostCoherent =
            (memoryFlags & VK_MEMORY_PROPERTY_HOST_COHERENT_BIT) != 0;
      } catch (...) {
        destroyReplayDiagnosticReadback(frame);
        throw;
      }
    }

    auto &prepared = frame.diagnosticReadback;
    prepared.colorOffset = 0;
    prepared.maskOffset = *maskOffset;
    prepared.depthOffset = *depthOffset;
    prepared.occlusionDepthOffset = occlusionDepthOffset;
    prepared.hostSceneDepthOffset = hostSceneDepthOffset;
    prepared.hostSceneDepthBytes = hostSceneDepthBytes;
    prepared.hasHostSceneDepth = false;
    prepared.scanoutColorOffset = scanoutColorOffset;
    prepared.otOwnerOffset = otOwnerOffset;
    prepared.strictOwnerOffset = strictOwnerOffset;
    prepared.liftedOwnerOffset = liftedOwnerOffset;
    prepared.otDepthOffset = otDepthOffset;
    prepared.strictDepthOffset = strictDepthOffset;
    prepared.liftedDepthOffset = liftedDepthOffset;
    prepared.otEvidenceOffset = otEvidenceOffset;
    prepared.strictEvidenceOffset = strictEvidenceOffset;
    prepared.liftedEvidenceOffset = liftedEvidenceOffset;
    prepared.visibilityStackOffset = visibilityStackOffset;
    prepared.colorBytes = colorBytes;
    prepared.maskBytes = maskBytes;
    prepared.depthBytes = depthBytes;
    prepared.occlusionDepthBytes = depthBytes;
    prepared.scanoutColorBytes = scanoutColorBytes;
    prepared.ownerBytes = ownerBytes;
    prepared.visibilityDepthBytes = visibilityDepthBytes;
    prepared.evidenceBytes = evidenceBytes;
    prepared.visibilityStackBytes = visibilityStackBytes;
    prepared.visibilityStackRecordCapacity = visibilityStackRecordCapacity;
    // Reservation happens before F8 reconstruction. Do not claim a readable
    // plane until the reconstruction succeeds below. A full visibility audit
    // always records strictDepth and is already authoritative here.
    prepared.hasPreCorrectionDepth = visibilityAudit;
    prepared.hasScanoutColor = scanoutColorBytes != 0u;
    prepared.scanoutWidth = prepared.hasScanoutColor ? scanoutExtent.width : 0u;
    prepared.scanoutHeight =
        prepared.hasScanoutColor ? scanoutExtent.height : 0u;
    prepared.region = region;
    if (visibilityStack) {
      VkDescriptorBufferInfo bufferInfo{};
      bufferInfo.buffer = prepared.buffer;
      bufferInfo.offset = prepared.visibilityStackOffset;
      bufferInfo.range = prepared.visibilityStackBytes;
      VkWriteDescriptorSet write{VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};
      write.dstSet = replayVisibilityResources.stackDescriptorSets[frameIndex];
      write.dstBinding = 0;
      write.descriptorCount = 1;
      write.descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER;
      write.pBufferInfo = &bufferInfo;
      vkUpdateDescriptorSets(device, 1, &write, 0, nullptr);
    }
  }

  std::optional<replay::VulkanReplayDiagnosticRegion>
  selectReplayDiagnosticRegion(
      const DisplayAperture &aperture, uint32_t internalScale,
      const replay::VulkanReplayBakedBatch *visibilityBatch) const {
    replay::VulkanReplayDiagnosticRegion region;
    if (replayReadbackConfig.fixedRegion.has_value()) {
      region = *replayReadbackConfig.fixedRegion;
    } else if (visibilityBatch != nullptr) {
      const replay::VulkanReplayVisibilityBoundsResult bounds =
          replay::measureVulkanReplayVisibilityBounds(*visibilityBatch);
      if (!bounds.complete() || internalScale == 0)
        return std::nullopt;
      const replay::VulkanReplayBakedRect &atlas = bounds.atlasArea;
      const uint64_t atlasRight = static_cast<uint64_t>(atlas.x) + atlas.width;
      const uint64_t atlasBottom =
          static_cast<uint64_t>(atlas.y) + atlas.height;
      const uint64_t nativeRight =
          (atlasRight + internalScale - 1u) / internalScale;
      const uint64_t nativeBottom =
          (atlasBottom + internalScale - 1u) / internalScale;
      region.nativeX = atlas.x / internalScale;
      region.nativeY = atlas.y / internalScale;
      if (nativeRight <= region.nativeX || nativeBottom <= region.nativeY ||
          nativeRight > GPU::VRAM_WIDTH || nativeBottom > GPU::VRAM_HEIGHT) {
        return std::nullopt;
      }
      region.nativeWidth = static_cast<uint32_t>(nativeRight - region.nativeX);
      region.nativeHeight =
          static_cast<uint32_t>(nativeBottom - region.nativeY);
    } else if (aperture.enabled && aperture.width != 0 &&
               aperture.height != 0 && aperture.x < GPU::VRAM_WIDTH &&
               aperture.y < GPU::VRAM_HEIGHT &&
               aperture.width <= GPU::VRAM_WIDTH - aperture.x &&
               aperture.height <= GPU::VRAM_HEIGHT - aperture.y) {
      region = {aperture.x, aperture.y, aperture.width, aperture.height, 1};
    } else {
      region = {0, 0, GPU::VRAM_WIDTH, GPU::VRAM_HEIGHT, 1};
    }
    region.internalScale = internalScale;
    if (region.nativeWidth == 0 || region.nativeHeight == 0 ||
        region.nativeX >= GPU::VRAM_WIDTH ||
        region.nativeY >= GPU::VRAM_HEIGHT ||
        region.nativeWidth > GPU::VRAM_WIDTH - region.nativeX ||
        region.nativeHeight > GPU::VRAM_HEIGHT - region.nativeY)
      return std::nullopt;
    return region;
  }

  bool prepareReplayDiagnosticReadback(
      FrameContext &frame, const DisplayAperture &aperture, uint64_t guestFrame,
      bool liveReanchor, const std::vector<Color16> &nativeSnapshotPixels,
      const replay::VulkanReplayBakedBatch *visibilityBatch,
      uint32_t frameIndex, bool preCorrectionDepth) {
    if (!replayReadbackConfig.selects(guestFrame, liveReanchor))
      return false;
    const auto selected = selectReplayDiagnosticRegion(
        aperture, replayResources.internalScale, visibilityBatch);
    if (!selected.has_value()) {
      ps1::metrics::count("host.renderer.vulkan_replay_readback.region_reject");
      if (visibilityBatch != nullptr)
        ps1::metrics::count("host.renderer.vulkan_visibility.region_reject");
      return false;
    }
    const bool visibilityCandidate =
        visibilityBatch != nullptr && replayVisibilityCandidateActive;
    const bool visibilityStack =
        visibilityBatch != nullptr && replayVisibilityStackActive;
    ensureReplayDiagnosticReadback(
        frame, *selected, preCorrectionDepth, visibilityBatch != nullptr,
        visibilityCandidate, visibilityStack, frameIndex);
    auto &readback = frame.diagnosticReadback;
    readback.guestFrame = guestFrame;
    readback.hasNativeOracle =
        liveReanchor &&
        nativeSnapshotPixels.size() >=
            static_cast<std::size_t>(GPU::VRAM_WIDTH) * GPU::VRAM_HEIGHT;
    if (readback.hasNativeOracle) {
      readback.nativeOracle.assign(
          nativeSnapshotPixels.begin(),
          nativeSnapshotPixels.begin() +
              static_cast<std::ptrdiff_t>(GPU::VRAM_WIDTH * GPU::VRAM_HEIGHT));
    } else {
      readback.nativeOracle.clear();
    }
    readback.hasVisibilityAudit = visibilityBatch != nullptr;
    readback.hasVisibilityCandidate = visibilityCandidate;
    readback.hasVisibilityStack = visibilityStack;
    readback.visibilityStackBarriers.clear();
    if (visibilityBatch != nullptr) {
      readback.visibilityOwners = visibilityBatch->visibilityOwners;
      const int64_t regionSource =
          replayReadbackConfig.fixedRegion.has_value() ? 1 : 2;
      ps1::metrics::setState(
          "host.renderer.vulkan_visibility.last_region_source", regionSource);
      ps1::metrics::setState(
          "host.renderer.vulkan_visibility.last_region_native_x",
          readback.region.nativeX);
      ps1::metrics::setState(
          "host.renderer.vulkan_visibility.last_region_native_y",
          readback.region.nativeY);
      ps1::metrics::setState(
          "host.renderer.vulkan_visibility.last_region_native_width",
          readback.region.nativeWidth);
      ps1::metrics::setState(
          "host.renderer.vulkan_visibility.last_region_native_height",
          readback.region.nativeHeight);
    } else {
      readback.visibilityOwners.clear();
    }
    return true;
  }

  void
  recordReplayDiagnosticReadback(VkCommandBuffer commandBuffer,
                                 FrameContext &frame,
                                 ReplayDiagnosticPresentation presentation =
                                     ReplayDiagnosticPresentation::Ordinary,
                                 bool includeCurrentHostSceneDepth = true) {
    auto &readback = frame.diagnosticReadback;
    // The legacy "operational-occlusion" file is replayResources.depth; the
    // host sidecar writes a different D32 attachment. Capture it separately,
    // only after a current submission has initialized the entire requested
    // region. Never label a stale/latch-only page as a current scene depth.
    const auto &hostArea = frame.hostSceneDepthRenderArea;
    const uint64_t depthX = static_cast<uint64_t>(readback.region.nativeX) *
                            readback.region.internalScale;
    const uint64_t depthY = static_cast<uint64_t>(readback.region.nativeY) *
                            readback.region.internalScale;
    readback.hasHostSceneDepth =
        includeCurrentHostSceneDepth && frame.hostSceneDepthRecorded &&
        readback.hostSceneDepthBytes != 0u && hostArea.offset.x >= 0 &&
        hostArea.offset.y >= 0 &&
        depthX >= static_cast<uint64_t>(hostArea.offset.x) &&
        depthY >= static_cast<uint64_t>(hostArea.offset.y) &&
        depthX + static_cast<uint64_t>(readback.region.nativeWidth) *
                     readback.region.internalScale <=
            static_cast<uint64_t>(hostArea.offset.x) + hostArea.extent.width &&
        depthY + static_cast<uint64_t>(readback.region.nativeHeight) *
                     readback.region.internalScale <=
            static_cast<uint64_t>(hostArea.offset.y) + hostArea.extent.height;
    if (readback.hostSceneDepthBytes != 0u)
      ps1::metrics::count(
          readback.hasHostSceneDepth
              ? "host.renderer.vulkan_replay_readback.host_scene_depth_captured"
              : "host.renderer.vulkan_replay_readback.host_scene_depth_"
                "unavailable");
    if (replayDiagnosticPresentationSerial ==
        std::numeric_limits<uint64_t>::max()) {
      throw std::overflow_error(
          "Vulkan replay diagnostic presentation serial overflow");
    }
    readback.presentationSerial = ++replayDiagnosticPresentationSerial;
    readback.presentation = presentation;
    if (ps1::metrics::traceEnabled()) {
      ps1::metrics::traceAtFrame(
          "renderer.vulkan_replay_readback.presentation", readback.guestFrame,
          {{"presentation_serial",
            static_cast<int64_t>(std::min<uint64_t>(
                readback.presentationSerial,
                static_cast<uint64_t>(std::numeric_limits<int64_t>::max())))},
           {"presentation", static_cast<int64_t>(readback.presentation)}});
    }
    std::array<VkImageMemoryBarrier, 14> toTransfer{};
    uint32_t transferImageCount = 4;
    const auto setBarrier = [](VkImageMemoryBarrier &barrier, VkImage image,
                               VkImageAspectFlags aspect,
                               VkImageLayout oldLayout,
                               VkAccessFlags sourceAccess) {
      barrier.sType = VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER;
      barrier.srcAccessMask = sourceAccess;
      barrier.dstAccessMask = VK_ACCESS_TRANSFER_READ_BIT;
      barrier.oldLayout = oldLayout;
      barrier.newLayout = VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL;
      barrier.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
      barrier.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
      barrier.image = image;
      barrier.subresourceRange.aspectMask = aspect;
      barrier.subresourceRange.levelCount = 1;
      barrier.subresourceRange.layerCount = 1;
    };
    const VkAccessFlags colorAccess = VK_ACCESS_COLOR_ATTACHMENT_READ_BIT |
                                      VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT;
    const VkAccessFlags depthAccess =
        VK_ACCESS_DEPTH_STENCIL_ATTACHMENT_READ_BIT |
        VK_ACCESS_DEPTH_STENCIL_ATTACHMENT_WRITE_BIT;
    setBarrier(toTransfer[0], replayResources.color.image,
               VK_IMAGE_ASPECT_COLOR_BIT,
               VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL, colorAccess);
    setBarrier(toTransfer[1], replayResources.mask.image,
               VK_IMAGE_ASPECT_COLOR_BIT,
               VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL, colorAccess);
    setBarrier(toTransfer[2], replayResources.surfaceDepth.image,
               VK_IMAGE_ASPECT_COLOR_BIT,
               VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL, colorAccess);
    setBarrier(toTransfer[3], replayResources.depth.image,
               VK_IMAGE_ASPECT_DEPTH_BIT,
               VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL, depthAccess);
    if (readback.hasVisibilityAudit) {
      if (!replayVisibilityResources.complete())
        throw std::runtime_error(
            "visibility readback outlived its Vulkan resources");
      setBarrier(toTransfer[4], replayVisibilityResources.otOwner.image,
                 VK_IMAGE_ASPECT_COLOR_BIT,
                 VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL, colorAccess);
      setBarrier(toTransfer[5], replayVisibilityResources.strictOwner.image,
                 VK_IMAGE_ASPECT_COLOR_BIT,
                 VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL, colorAccess);
      setBarrier(toTransfer[6], replayVisibilityResources.otDepth.image,
                 VK_IMAGE_ASPECT_DEPTH_BIT,
                 VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL, depthAccess);
      setBarrier(toTransfer[7], replayVisibilityResources.strictDepth.image,
                 VK_IMAGE_ASPECT_DEPTH_BIT,
                 VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL, depthAccess);
      setBarrier(toTransfer[8], replayVisibilityResources.otEvidence.image,
                 VK_IMAGE_ASPECT_COLOR_BIT,
                 VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL, colorAccess);
      setBarrier(toTransfer[9], replayVisibilityResources.strictEvidence.image,
                 VK_IMAGE_ASPECT_COLOR_BIT,
                 VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL, colorAccess);
      transferImageCount = 10;
      if (readback.hasVisibilityCandidate) {
        if (!replayVisibilityResources.liftedCandidate)
          throw std::runtime_error(
              "candidate readback outlived its Vulkan resources");
        setBarrier(toTransfer[10], replayVisibilityResources.liftedOwner.image,
                   VK_IMAGE_ASPECT_COLOR_BIT,
                   VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL, colorAccess);
        setBarrier(toTransfer[11], replayVisibilityResources.liftedDepth.image,
                   VK_IMAGE_ASPECT_DEPTH_BIT,
                   VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL,
                   depthAccess);
        setBarrier(toTransfer[12],
                   replayVisibilityResources.liftedEvidence.image,
                   VK_IMAGE_ASPECT_COLOR_BIT,
                   VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL, colorAccess);
        transferImageCount = 13u;
      }
    } else if (readback.hasPreCorrectionDepth) {
      if (!replayVisibilityResources.complete())
        throw std::runtime_error(
            "pre-correction depth readback outlived its Vulkan resources");
      setBarrier(toTransfer[4], replayVisibilityResources.strictDepth.image,
                 VK_IMAGE_ASPECT_DEPTH_BIT,
                 VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL, depthAccess);
      transferImageCount = 5u;
    }
    if (readback.hasHostSceneDepth) {
      setBarrier(toTransfer[transferImageCount++],
                 replayGeometryResources.crash3SceneryDepth.image,
                 VK_IMAGE_ASPECT_DEPTH_BIT,
                 VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL, depthAccess);
    }
    if (readback.hasVisibilityStack &&
        !replayVisibilityResources.fragmentStack) {
      throw std::runtime_error(
          "visibility stack readback outlived its Vulkan resources");
    }
    const VkPipelineStageFlags attachmentStages =
        VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT |
        VK_PIPELINE_STAGE_EARLY_FRAGMENT_TESTS_BIT |
        VK_PIPELINE_STAGE_LATE_FRAGMENT_TESTS_BIT;
    vkCmdPipelineBarrier(commandBuffer, attachmentStages,
                         VK_PIPELINE_STAGE_TRANSFER_BIT, 0, 0, nullptr, 0,
                         nullptr, transferImageCount, toTransfer.data());

    const auto imageCopy = [&readback](VkDeviceSize offset,
                                       VkImageAspectFlags aspect) {
      VkBufferImageCopy copy{};
      copy.bufferOffset = offset;
      copy.bufferRowLength = 0;
      copy.bufferImageHeight = 0;
      copy.imageSubresource.aspectMask = aspect;
      copy.imageSubresource.mipLevel = 0;
      copy.imageSubresource.baseArrayLayer = 0;
      copy.imageSubresource.layerCount = 1;
      copy.imageOffset = {static_cast<int32_t>(readback.region.nativeX *
                                               readback.region.internalScale),
                          static_cast<int32_t>(readback.region.nativeY *
                                               readback.region.internalScale),
                          0};
      copy.imageExtent = {
          readback.region.nativeWidth * readback.region.internalScale,
          readback.region.nativeHeight * readback.region.internalScale, 1};
      return copy;
    };
    const VkBufferImageCopy colorCopy =
        imageCopy(readback.colorOffset, VK_IMAGE_ASPECT_COLOR_BIT);
    const VkBufferImageCopy maskCopy =
        imageCopy(readback.maskOffset, VK_IMAGE_ASPECT_COLOR_BIT);
    const VkBufferImageCopy depthCopy =
        imageCopy(readback.depthOffset, VK_IMAGE_ASPECT_COLOR_BIT);
    const VkBufferImageCopy occlusionDepthCopy =
        imageCopy(readback.occlusionDepthOffset, VK_IMAGE_ASPECT_DEPTH_BIT);
    vkCmdCopyImageToBuffer(commandBuffer, replayResources.color.image,
                           VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,
                           readback.buffer, 1, &colorCopy);
    vkCmdCopyImageToBuffer(commandBuffer, replayResources.mask.image,
                           VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,
                           readback.buffer, 1, &maskCopy);
    vkCmdCopyImageToBuffer(commandBuffer, replayResources.surfaceDepth.image,
                           VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,
                           readback.buffer, 1, &depthCopy);
    vkCmdCopyImageToBuffer(commandBuffer, replayResources.depth.image,
                           VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,
                           readback.buffer, 1, &occlusionDepthCopy);
    if (readback.hasHostSceneDepth) {
      const VkBufferImageCopy hostDepthCopy =
          imageCopy(readback.hostSceneDepthOffset, VK_IMAGE_ASPECT_DEPTH_BIT);
      vkCmdCopyImageToBuffer(commandBuffer,
                             replayGeometryResources.crash3SceneryDepth.image,
                             VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,
                             readback.buffer, 1, &hostDepthCopy);
    }
    if (readback.hasScanoutColor) {
      if (scanoutColorImage == VK_NULL_HANDLE ||
          readback.scanoutWidth != scanoutExtent.width ||
          readback.scanoutHeight != scanoutExtent.height) {
        throw std::runtime_error(
            "Vulkan scanout changed after diagnostic preparation");
      }
      VkImageMemoryBarrier scanoutToTransfer{
          VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER};
      scanoutToTransfer.srcAccessMask = VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT;
      scanoutToTransfer.dstAccessMask = VK_ACCESS_TRANSFER_READ_BIT;
      scanoutToTransfer.oldLayout = VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL;
      scanoutToTransfer.newLayout = VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL;
      scanoutToTransfer.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
      scanoutToTransfer.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
      scanoutToTransfer.image = scanoutColorImage;
      scanoutToTransfer.subresourceRange.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
      scanoutToTransfer.subresourceRange.levelCount = 1u;
      scanoutToTransfer.subresourceRange.layerCount = 1u;
      vkCmdPipelineBarrier(commandBuffer,
                           VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT,
                           VK_PIPELINE_STAGE_TRANSFER_BIT, 0u, 0u, nullptr, 0u,
                           nullptr, 1u, &scanoutToTransfer);
      VkBufferImageCopy scanoutCopy{};
      scanoutCopy.bufferOffset = readback.scanoutColorOffset;
      scanoutCopy.imageSubresource.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;
      scanoutCopy.imageSubresource.layerCount = 1u;
      scanoutCopy.imageExtent = {readback.scanoutWidth, readback.scanoutHeight,
                                 1u};
      vkCmdCopyImageToBuffer(commandBuffer, scanoutColorImage,
                             VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,
                             readback.buffer, 1u, &scanoutCopy);
      VkImageMemoryBarrier scanoutToShader = scanoutToTransfer;
      scanoutToShader.srcAccessMask = VK_ACCESS_TRANSFER_READ_BIT;
      scanoutToShader.dstAccessMask = VK_ACCESS_SHADER_READ_BIT;
      scanoutToShader.oldLayout = VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL;
      scanoutToShader.newLayout = VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL;
      vkCmdPipelineBarrier(commandBuffer, VK_PIPELINE_STAGE_TRANSFER_BIT,
                           VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT, 0u, 0u,
                           nullptr, 0u, nullptr, 1u, &scanoutToShader);
    }
    if (readback.hasVisibilityAudit) {
      const auto copyVisibility = [&](VkImage image, VkDeviceSize offset,
                                      VkImageAspectFlags aspect) {
        const VkBufferImageCopy copy = imageCopy(offset, aspect);
        vkCmdCopyImageToBuffer(commandBuffer, image,
                               VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,
                               readback.buffer, 1, &copy);
      };
      copyVisibility(replayVisibilityResources.otOwner.image,
                     readback.otOwnerOffset, VK_IMAGE_ASPECT_COLOR_BIT);
      copyVisibility(replayVisibilityResources.strictOwner.image,
                     readback.strictOwnerOffset, VK_IMAGE_ASPECT_COLOR_BIT);
      copyVisibility(replayVisibilityResources.otDepth.image,
                     readback.otDepthOffset, VK_IMAGE_ASPECT_DEPTH_BIT);
      copyVisibility(replayVisibilityResources.strictDepth.image,
                     readback.strictDepthOffset, VK_IMAGE_ASPECT_DEPTH_BIT);
      copyVisibility(replayVisibilityResources.otEvidence.image,
                     readback.otEvidenceOffset, VK_IMAGE_ASPECT_COLOR_BIT);
      copyVisibility(replayVisibilityResources.strictEvidence.image,
                     readback.strictEvidenceOffset, VK_IMAGE_ASPECT_COLOR_BIT);
      if (readback.hasVisibilityCandidate) {
        copyVisibility(replayVisibilityResources.liftedOwner.image,
                       readback.liftedOwnerOffset, VK_IMAGE_ASPECT_COLOR_BIT);
        copyVisibility(replayVisibilityResources.liftedDepth.image,
                       readback.liftedDepthOffset, VK_IMAGE_ASPECT_DEPTH_BIT);
        copyVisibility(replayVisibilityResources.liftedEvidence.image,
                       readback.liftedEvidenceOffset,
                       VK_IMAGE_ASPECT_COLOR_BIT);
      }
    } else if (readback.hasPreCorrectionDepth) {
      const VkBufferImageCopy preCorrectionDepthCopy =
          imageCopy(readback.strictDepthOffset, VK_IMAGE_ASPECT_DEPTH_BIT);
      vkCmdCopyImageToBuffer(commandBuffer,
                             replayVisibilityResources.strictDepth.image,
                             VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,
                             readback.buffer, 1, &preCorrectionDepthCopy);
    }

    VkBufferMemoryBarrier toHost{VK_STRUCTURE_TYPE_BUFFER_MEMORY_BARRIER};
    toHost.srcAccessMask =
        VK_ACCESS_TRANSFER_WRITE_BIT |
        (readback.hasVisibilityStack ? VK_ACCESS_SHADER_WRITE_BIT
                                     : VkAccessFlags{0});
    toHost.dstAccessMask = VK_ACCESS_HOST_READ_BIT;
    toHost.srcQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
    toHost.dstQueueFamilyIndex = VK_QUEUE_FAMILY_IGNORED;
    toHost.buffer = readback.buffer;
    toHost.offset = 0;
    toHost.size =
        readback.hasVisibilityStack
            ? readback.visibilityStackOffset + readback.visibilityStackBytes
        : readback.hasVisibilityCandidate
            ? readback.liftedEvidenceOffset + readback.evidenceBytes
        : readback.hasVisibilityAudit
            ? readback.strictEvidenceOffset + readback.evidenceBytes
        : readback.hasPreCorrectionDepth
            ? readback.strictDepthOffset + readback.visibilityDepthBytes
        : readback.hasScanoutColor
            ? readback.scanoutColorOffset + readback.scanoutColorBytes
        : readback.hasHostSceneDepth
            ? readback.hostSceneDepthOffset + readback.hostSceneDepthBytes
            : readback.occlusionDepthOffset + readback.occlusionDepthBytes;

    std::array<VkImageMemoryBarrier, 14> toAttachment = toTransfer;
    for (uint32_t index = 0; index < transferImageCount; ++index) {
      auto &barrier = toAttachment[index];
      barrier.srcAccessMask = VK_ACCESS_TRANSFER_READ_BIT;
      barrier.oldLayout = VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL;
      if ((barrier.subresourceRange.aspectMask & VK_IMAGE_ASPECT_DEPTH_BIT) !=
          0) {
        barrier.dstAccessMask = depthAccess;
        barrier.newLayout = VK_IMAGE_LAYOUT_DEPTH_STENCIL_ATTACHMENT_OPTIMAL;
      } else {
        barrier.dstAccessMask = colorAccess;
        barrier.newLayout = VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL;
      }
    }
    const VkPipelineStageFlags readbackSourceStages =
        VK_PIPELINE_STAGE_TRANSFER_BIT |
        (readback.hasVisibilityStack ? VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT
                                     : VkPipelineStageFlags{0});
    vkCmdPipelineBarrier(commandBuffer, readbackSourceStages,
                         attachmentStages | VK_PIPELINE_STAGE_HOST_BIT, 0, 0,
                         nullptr, 1, &toHost, transferImageCount,
                         toAttachment.data());
  }

  void disableReplayReadback(std::string_view reason) {
    replayReadbackConfig.active = false;
    replayVisibilityAuditActive = false;
    replayVisibilityCandidateActive = false;
    replayVisibilityStackActive = false;
    ps1::metrics::setState("host.renderer.vulkan_replay_readback_active", 0);
    ps1::metrics::setState("host.renderer.vulkan_visibility.active", 0);
    ps1::metrics::setState("host.renderer.vulkan_visibility.catalog_active", 0);
    ps1::metrics::setState("host.renderer.vulkan_visibility.candidate_active",
                           0);
    ps1::metrics::setState("host.renderer.vulkan_visibility.stack_active", 0);
    ps1::metrics::count("host.renderer.vulkan_replay_readback.disabled_error");
    fmt::print(stderr, "[RendererVK] replay readback disabled: {}\n", reason);
  }

  void disableReplayVisibilityAudit(std::string_view reason) {
    replayVisibilityAuditActive = false;
    replayVisibilityCandidateActive = false;
    replayVisibilityStackActive = false;
    ps1::metrics::setState("host.renderer.vulkan_visibility.active", 0);
    ps1::metrics::setState("host.renderer.vulkan_visibility.catalog_active", 0);
    ps1::metrics::setState("host.renderer.vulkan_visibility.candidate_active",
                           0);
    ps1::metrics::setState("host.renderer.vulkan_visibility.stack_active", 0);
    ps1::metrics::count("host.renderer.vulkan_visibility.disabled_error");
    fmt::print(stderr, "[RendererVK] visibility audit disabled: {}\n", reason);
  }

  void configureConstructionLineageAdmission() {
    const bool rendererOwnsConstructionLineage =
        replayVisibilityCandidateManifestRequested ||
        replayVisibilityStackRequested || replayPresentationWipRequested;
    if (!rendererOwnsConstructionLineage)
      return;

    const bool exhaustiveIdentityRequested =
        replayVisibilityStackActive ||
        (replayVisibilityCandidateManifestRequested &&
         replayVisibilityCandidateActive);
    if (exhaustiveIdentityRequested) {
      // Capture tooling must observe every transform; an empty filter means
      // intentionally unfiltered rather than no admission.
      ps1::mips::setConstructionLineageTransformFilter(
          std::span<const uint64_t>{});
      ps1::mips::setConstructionLineageSeedFilter(
          std::span<const ps1::mips::ConstructionLineageSeed>{});
      ps1::mips::setConstructionLineageEnabled(true);
      ps1::metrics::setState(
          "host.renderer.vulkan_construction_lineage.filtered", 0);
      ps1::metrics::setState(
          "host.renderer.vulkan_construction_lineage.transforms", 0);
      ps1::metrics::setState("host.renderer.vulkan_construction_lineage.seeds",
                             0);
      return;
    }

    if (!replayPresentationWipActive) {
      // A requested but rejected/unsupported preview must not tax guest
      // execution. A later successful hot reload will arm it again.
      ps1::mips::setConstructionLineageEnabled(false);
      ps1::mips::setConstructionLineageSeedFilter(
          std::span<const ps1::mips::ConstructionLineageSeed>{});
      ps1::metrics::setState(
          "host.renderer.vulkan_construction_lineage.filtered", 0);
      ps1::metrics::setState(
          "host.renderer.vulkan_construction_lineage.transforms", 0);
      ps1::metrics::setState("host.renderer.vulkan_construction_lineage.seeds",
                             0);
      return;
    }

    std::vector<uint64_t> transformLineages;
    std::vector<ps1::mips::ConstructionLineageSeed> constructionSeeds;
    const replay::ReplayVisibilityManifestSnapshot &snapshot =
        replayPresentationWipManifest.snapshot();
    transformLineages.reserve(snapshot.entries.size());
    for (const replay::ReplayVisibilityManifestEntry &entry :
         snapshot.entries) {
      transformLineages.push_back(entry.key.transformLineage);
    }
    constructionSeeds.reserve(snapshot.constructionSeeds.size());
    for (const replay::ReplayVisibilityConstructionSeed &seed :
         snapshot.constructionSeeds) {
      constructionSeeds.push_back({seed.pc, seed.rawInstruction,
                                   seed.sourceAddress, seed.sourceRegister});
    }
    std::sort(transformLineages.begin(), transformLineages.end());
    transformLineages.erase(
        std::unique(transformLineages.begin(), transformLineages.end()),
        transformLineages.end());
    if (transformLineages.empty() || constructionSeeds.empty()) {
      ps1::mips::setConstructionLineageEnabled(false);
      ps1::mips::setConstructionLineageSeedFilter(
          std::span<const ps1::mips::ConstructionLineageSeed>{});
      ps1::metrics::setState("host.renderer.vulkan_construction_lineage.seeds",
                             0);
      return;
    }

    // The presentation manifest is categorical evidence, not a visual
    // heuristic. Its exact transform keys let the interpreter remain on its
    // plain path until a potentially dispatchable projection is observed.
    ps1::mips::setConstructionLineageTransformFilter(transformLineages);
    ps1::mips::setConstructionLineageSeedFilter(constructionSeeds);
    ps1::mips::setConstructionLineageEnabled(true);
    ps1::metrics::setState("host.renderer.vulkan_construction_lineage.filtered",
                           1);
    ps1::metrics::setState(
        "host.renderer.vulkan_construction_lineage.transforms",
        static_cast<int64_t>(transformLineages.size()));
    ps1::metrics::setState("host.renderer.vulkan_construction_lineage.seeds",
                           static_cast<int64_t>(constructionSeeds.size()));
  }

  void publishReplayVisibilityManifestMetrics() const {
    const replay::ReplayVisibilityManifestSnapshot &snapshot =
        replayVisibilityCandidateManifest.snapshot();
    ps1::metrics::setState(
        "host.renderer.vulkan_visibility.candidate_manifest_requested",
        replayVisibilityCandidateManifestRequested ? 1 : 0);
    ps1::metrics::setState(
        "host.renderer.vulkan_visibility.candidate_manifest_ready",
        snapshot.ready() ? 1 : 0);
    ps1::metrics::setState(
        "host.renderer.vulkan_visibility.candidate_manifest_status",
        static_cast<int64_t>(snapshot.status));
    ps1::metrics::setState(
        "host.renderer.vulkan_visibility.candidate_manifest_generation",
        static_cast<int64_t>(replayVisibilityCandidateManifest.generation()));
    ps1::metrics::setState(
        "host.renderer.vulkan_visibility.candidate_manifest_components",
        static_cast<int64_t>(snapshot.components.size()));
    ps1::metrics::setState(
        "host.renderer.vulkan_visibility.candidate_manifest_entries",
        static_cast<int64_t>(snapshot.entries.size()));
  }

  void refreshReplayVisibilityManifest() {
    if (!replayVisibilityCandidateManifestRequested)
      return;
    const uint64_t previousGeneration =
        replayVisibilityCandidateManifest.generation();
    replayVisibilityCandidateManifest.reloadIfChanged();
    if (replayVisibilityCandidateManifest.generation() == previousGeneration)
      return;

    const replay::ReplayVisibilityManifestSnapshot &snapshot =
        replayVisibilityCandidateManifest.snapshot();
    publishReplayVisibilityManifestMetrics();
    ps1::metrics::count(
        "host.renderer.vulkan_visibility.candidate_manifest_reload");
    if (snapshot.ready()) {
      ps1::metrics::count(
          "host.renderer.vulkan_visibility.candidate_manifest_reload_ready");
      fmt::print("[RendererVK] visibility candidate manifest reloaded: {} "
                 "components, {} dispatch entries\n",
                 snapshot.components.size(), snapshot.entries.size());
    } else {
      ps1::metrics::count(
          "host.renderer.vulkan_visibility.candidate_manifest_reload_rejected");
      fmt::print(stderr,
                 "[RendererVK] visibility candidate manifest rejected "
                 "fail-closed: {} ({})\n",
                 replay::replayVisibilityManifestStatusName(snapshot.status),
                 snapshot.error);
    }
  }

  void publishReplayPresentationWipMetrics() const {
    const replay::ReplayVisibilityManifestSnapshot &snapshot =
        replayPresentationWipManifest.snapshot();
    ps1::metrics::setState("host.renderer.vulkan_depth_wip.requested",
                           replayPresentationWipRequested ? 1 : 0);
    ps1::metrics::setState("host.renderer.vulkan_depth_wip.profile_supported",
                           replayPresentationWipProfileSupported ? 1 : 0);
    ps1::metrics::setState("host.renderer.vulkan_depth_wip.active",
                           replayPresentationWipActive ? 1 : 0);
    ps1::metrics::setState("host.renderer.vulkan_depth_wip.manifest_ready",
                           snapshot.ready() ? 1 : 0);
    ps1::metrics::setState("host.renderer.vulkan_depth_wip.manifest_status",
                           static_cast<int64_t>(snapshot.status));
    ps1::metrics::setState(
        "host.renderer.vulkan_depth_wip.manifest_generation",
        static_cast<int64_t>(replayPresentationWipManifest.generation()));
    ps1::metrics::setState("host.renderer.vulkan_depth_wip.manifest_components",
                           static_cast<int64_t>(snapshot.components.size()));
    ps1::metrics::setState("host.renderer.vulkan_depth_wip.manifest_entries",
                           static_cast<int64_t>(snapshot.entries.size()));
  }

  void refreshReplayPresentationWipManifest() {
    if (!replayPresentationWipRequested)
      return;
    const uint64_t previousGeneration =
        replayPresentationWipManifest.generation();
    replayPresentationWipManifest.reloadIfChanged();
    if (replayPresentationWipManifest.generation() == previousGeneration)
      return;

    const replay::ReplayVisibilityManifestSnapshot &snapshot =
        replayPresentationWipManifest.snapshot();
    replayPresentationWipActive =
        replayPresentationWipProfileSupported && snapshot.ready();
    configureConstructionLineageAdmission();
    publishReplayPresentationWipMetrics();
    ps1::metrics::count("host.renderer.vulkan_depth_wip.manifest_reload");
    if (replayPresentationWipActive) {
      ps1::metrics::count(
          "host.renderer.vulkan_depth_wip.manifest_reload_ready");
      fmt::print("[RendererVK] WIP presentation-depth manifest reloaded: {} "
                 "components, {} dispatch entries\n",
                 snapshot.components.size(), snapshot.entries.size());
    } else {
      ps1::metrics::count(
          "host.renderer.vulkan_depth_wip.manifest_reload_rejected");
      fmt::print(stderr,
                 "[RendererVK] WIP presentation-depth correction disabled "
                 "fail-closed: {} ({})\n",
                 replay::replayVisibilityManifestStatusName(snapshot.status),
                 snapshot.error);
    }
  }

  void consumeReplayDiagnosticReadback(FrameContext &frame) {
    auto &readback = frame.diagnosticReadback;
    if (!readback.pending)
      return;
    readback.pending = false;
    try {
      if (!readback.hostCoherent) {
        VkMappedMemoryRange range{VK_STRUCTURE_TYPE_MAPPED_MEMORY_RANGE};
        range.memory = readback.memory;
        range.offset = 0;
        range.size = VK_WHOLE_SIZE;
        const VkResult invalidated =
            vkInvalidateMappedMemoryRanges(device, 1, &range);
        if (invalidated != VK_SUCCESS) {
          disableReplayReadback(
              fmt::format("vkInvalidateMappedMemoryRanges returned {}",
                          static_cast<int>(invalidated)));
          readback.nativeOracle.clear();
          readback.visibilityOwners.clear();
          readback.visibilityStackBarriers.clear();
          readback.hasPreCorrectionDepth = false;
          readback.hasVisibilityAudit = false;
          readback.hasVisibilityCandidate = false;
          readback.hasVisibilityStack = false;
          return;
        }
      }

      const uint32_t scaledWidth =
          readback.region.nativeWidth * readback.region.internalScale;
      const uint32_t scaledHeight =
          readback.region.nativeHeight * readback.region.internalScale;
      const auto *base = static_cast<const std::byte *>(readback.mapped);
      const replay::VulkanReplayDiagnosticPlanes planes{
          {base + readback.colorOffset,
           static_cast<std::size_t>(readback.colorBytes),
           static_cast<std::size_t>(scaledWidth) * sizeof(Color32)},
          {base + readback.maskOffset,
           static_cast<std::size_t>(readback.maskBytes), scaledWidth},
          {base + readback.depthOffset,
           static_cast<std::size_t>(readback.depthBytes),
           static_cast<std::size_t>(scaledWidth) * sizeof(float)}};
      if (!replayReadbackConfig.colorDumpDirectory.empty()) {
        const std::string filename =
            replayReadbackConfig.temporalMidpoint
                ? fmt::format(
                      "frame-{}-present-{}-{}.ppm", readback.guestFrame,
                      readback.presentationSerial,
                      replayDiagnosticPresentationName(readback.presentation))
                : fmt::format("frame-{}.ppm", readback.guestFrame);
        const std::filesystem::path path =
            replayReadbackConfig.colorDumpDirectory / filename;
        std::ofstream stream(path, std::ios::binary | std::ios::trunc);
        if (!stream) {
          fmt::print(stderr,
                     "[RendererVK] cannot write replay color dump '{}'\n",
                     path.string());
          ps1::metrics::count(
              "host.renderer.vulkan_replay_readback.dump_failed");
        } else {
          stream << "P6\n" << scaledWidth << ' ' << scaledHeight << "\n255\n";
          const auto *colors =
              reinterpret_cast<const Color32 *>(base + readback.colorOffset);
          std::vector<uint8_t> row(static_cast<std::size_t>(scaledWidth) * 3u);
          for (uint32_t y = 0; y < scaledHeight; ++y) {
            for (uint32_t x = 0; x < scaledWidth; ++x) {
              const Color32 color =
                  colors[static_cast<std::size_t>(y) * scaledWidth + x];
              row[x * 3u + 0u] = color.r;
              row[x * 3u + 1u] = color.g;
              row[x * 3u + 2u] = color.b;
            }
            stream.write(reinterpret_cast<const char *>(row.data()),
                         static_cast<std::streamsize>(row.size()));
          }
          if (!stream) {
            fmt::print(stderr, "[RendererVK] short replay color dump '{}'\n",
                       path.string());
            ps1::metrics::count(
                "host.renderer.vulkan_replay_readback.dump_failed");
          } else {
            ps1::metrics::count(
                "host.renderer.vulkan_replay_readback.dump_written");
          }
        }
        if (readback.hasScanoutColor) {
          const std::filesystem::path scanoutPath =
              replayReadbackConfig.colorDumpDirectory /
              fmt::format(
                  "frame-{}-present-{}-{}-scanout.ppm", readback.guestFrame,
                  readback.presentationSerial,
                  replayDiagnosticPresentationName(readback.presentation));
          std::ofstream scanoutStream(scanoutPath,
                                      std::ios::binary | std::ios::trunc);
          if (!scanoutStream) {
            fmt::print(stderr,
                       "[RendererVK] cannot write scanout color dump '{}'\n",
                       scanoutPath.string());
            ps1::metrics::count(
                "host.renderer.vulkan_replay_readback.scanout_dump_failed");
          } else {
            scanoutStream << "P6\n"
                          << readback.scanoutWidth << ' '
                          << readback.scanoutHeight << "\n255\n";
            const auto *colors = reinterpret_cast<const Color32 *>(
                base + readback.scanoutColorOffset);
            std::vector<uint8_t> row(
                static_cast<std::size_t>(readback.scanoutWidth) * 3u);
            for (uint32_t y = 0; y < readback.scanoutHeight; ++y) {
              for (uint32_t x = 0; x < readback.scanoutWidth; ++x) {
                const Color32 color =
                    colors[static_cast<std::size_t>(y) * readback.scanoutWidth +
                           x];
                row[x * 3u + 0u] = color.r;
                row[x * 3u + 1u] = color.g;
                row[x * 3u + 2u] = color.b;
              }
              scanoutStream.write(reinterpret_cast<const char *>(row.data()),
                                  static_cast<std::streamsize>(row.size()));
            }
            if (!scanoutStream) {
              fmt::print(stderr, "[RendererVK] short scanout color dump '{}'\n",
                         scanoutPath.string());
              ps1::metrics::count(
                  "host.renderer.vulkan_replay_readback.scanout_dump_failed");
            } else {
              ps1::metrics::count(
                  "host.renderer.vulkan_replay_readback.scanout_dump_written");
            }
          }
        }
      }
      if (!replayReadbackConfig.depthDumpDirectory.empty()) {
        const std::string filenameStem =
            replayReadbackConfig.temporalMidpoint
                ? fmt::format(
                      "frame-{}-present-{}-{}", readback.guestFrame,
                      readback.presentationSerial,
                      replayDiagnosticPresentationName(readback.presentation))
                : fmt::format("frame-{}", readback.guestFrame);
        const std::filesystem::path path =
            replayReadbackConfig.depthDumpDirectory /
            fmt::format("{}.ppm", filenameStem);
        const auto *depth =
            reinterpret_cast<const float *>(base + readback.depthOffset);
        std::ofstream stream(path, std::ios::binary | std::ios::trunc);
        if (!stream) {
          fmt::print(stderr,
                     "[RendererVK] cannot write replay depth dump '{}'\n",
                     path.string());
          ps1::metrics::count(
              "host.renderer.vulkan_replay_readback.depth_dump_failed");
        } else {
          stream << "P6\n" << scaledWidth << ' ' << scaledHeight << "\n255\n";
          std::vector<uint8_t> row(static_cast<std::size_t>(scaledWidth) * 3u);
          const auto falseColour = [](float encoded) {
            std::array<uint8_t, 3> rgb{};
            if (!std::isfinite(encoded) || encoded <= 0.0f || encoded >= 1.0f)
              return rgb;
            constexpr double kDepthDomain = 4294967296.0;
            const double rawW =
                std::max(static_cast<double>(encoded) * kDepthDomain, 1.0);
            // Match present_replay_depth.frag: expand Crash's measured scene
            // range without synthetic isolines. The camera-enclosing sky
            // sentinel remains a distinct far blue.
            const bool sky = rawW >= 2147483648.0;
            const double logW = std::log2(rawW);
            const double normalizedLogDepth =
                sky ? 1.0 : std::clamp((logW - 12.0) / 6.0, 0.0, 1.0);
            const double hue6 = normalizedLogDepth * 4.0;
            constexpr std::array<double, 3> kPhase{{0.0, 4.0, 2.0}};
            for (std::size_t component = 0u; component < rgb.size();
                 ++component) {
              const double phase =
                  std::abs(std::fmod(hue6 + kPhase[component], 6.0) - 3.0);
              const double value = std::clamp(phase - 1.0, 0.0, 1.0);
              rgb[component] = static_cast<uint8_t>(std::lround(value * 255.0));
            }
            return rgb;
          };
          for (uint32_t y = 0; y < scaledHeight; ++y) {
            for (uint32_t x = 0; x < scaledWidth; ++x) {
              const auto rgb = falseColour(
                  depth[static_cast<std::size_t>(y) * scaledWidth + x]);
              row[x * 3u + 0u] = rgb[0];
              row[x * 3u + 1u] = rgb[1];
              row[x * 3u + 2u] = rgb[2];
            }
            stream.write(reinterpret_cast<const char *>(row.data()),
                         static_cast<std::streamsize>(row.size()));
          }
          if (!stream) {
            fmt::print(stderr, "[RendererVK] short replay depth dump '{}'\n",
                       path.string());
            ps1::metrics::count(
                "host.renderer.vulkan_replay_readback.depth_dump_failed");
          } else {
            ps1::metrics::count(
                "host.renderer.vulkan_replay_readback.depth_dump_written");
          }
        }
        if (replayReadbackConfig.rawDepthDump) {
          const auto writeRawDepth = [&](std::string_view plane,
                                         const float *samples) {
            const std::filesystem::path rawPath =
                replayReadbackConfig.depthDumpDirectory /
                fmt::format("{}.{}.pfm", filenameStem, plane);
            std::ofstream rawStream(rawPath,
                                    std::ios::binary | std::ios::trunc);
            if (!rawStream) {
              fmt::print(stderr,
                         "[RendererVK] cannot write raw replay depth dump "
                         "'{}'\n",
                         rawPath.string());
              ps1::metrics::count(
                  "host.renderer.vulkan_replay_readback.raw_depth_dump_"
                  "failed");
              return;
            }
            // PFM rows are bottom-to-top. A negative scale identifies the
            // little-endian IEEE-754 payload emitted on supported hosts.
            static_assert(std::endian::native == std::endian::little,
                          "raw Vulkan depth PFM requires little endian");
            rawStream << "Pf\n"
                      << scaledWidth << ' ' << scaledHeight << "\n-1.0\n";
            const std::streamsize rowBytes = static_cast<std::streamsize>(
                static_cast<std::size_t>(scaledWidth) * sizeof(float));
            for (uint32_t row = scaledHeight; row-- > 0u;) {
              rawStream.write(
                  reinterpret_cast<const char *>(
                      samples + static_cast<std::size_t>(row) * scaledWidth),
                  rowBytes);
            }
            if (!rawStream) {
              fmt::print(stderr,
                         "[RendererVK] short raw replay depth dump '{}'\n",
                         rawPath.string());
              ps1::metrics::count(
                  "host.renderer.vulkan_replay_readback.raw_depth_dump_failed");
            } else {
              ps1::metrics::count("host.renderer.vulkan_replay_readback.raw_"
                                  "depth_dump_written");
            }
          };
          writeRawDepth("presented-surface-r32", depth);
          writeRawDepth("operational-occlusion-d32",
                        reinterpret_cast<const float *>(
                            base + readback.occlusionDepthOffset));
          if (readback.hasHostSceneDepth)
            writeRawDepth("host-scene-occlusion-d32",
                          reinterpret_cast<const float *>(
                              base + readback.hostSceneDepthOffset));
          if (readback.hasPreCorrectionDepth) {
            writeRawDepth("pre-raw-w-d32",
                          reinterpret_cast<const float *>(
                              base + readback.strictDepthOffset));
          }
        }
      }
      replay::VulkanReplayDiagnosticReport report;
      if (readback.hasNativeOracle) {
        report = replay::diagnoseVulkanReplayReadback(
            readback.region, planes,
            replay::VulkanReplayDiagnosticOracleView::fromNativeSeed(
                readback.nativeOracle.data(), readback.nativeOracle.size(),
                GPU::VRAM_WIDTH, GPU::VRAM_HEIGHT,
                readback.region.internalScale));
      } else {
        report = replay::captureVulkanReplayReadback(readback.region, planes);
      }
      replay::publishVulkanReplayDiagnosticMetrics(report, readback.guestFrame);
      ps1::metrics::count("host.renderer.vulkan_replay_readback.completed");
      if (readback.hasNativeOracle)
        ps1::metrics::count(
            "host.renderer.vulkan_replay_readback.oracle_native");
      else
        ps1::metrics::count("host.renderer.vulkan_replay_readback.actual_only");
      fmt::print(
          "[RendererVK] replay readback frame {} {} {}x{}@({},{}): "
          "rgba={:016x} mask={:016x} depth={:016x} mismatches={} "
          "invalid_depth={} surface_depth={}/{} nonblack_sentinel={}\n",
          readback.guestFrame,
          replay::vulkanReplayDiagnosticStatusName(report.status), scaledWidth,
          scaledHeight, readback.region.nativeX * readback.region.internalScale,
          readback.region.nativeY * readback.region.internalScale,
          report.actual.rgba8, report.actual.maskR8, report.actual.depthD32,
          report.anyMismatchPixels, report.actualInvalidDepthPixels,
          report.actualSurfaceDepthPixels, report.comparedPixels,
          report.actualNonBlackSurfaceDepthSentinelPixels);
      if (readback.hasVisibilityAudit) {
        const std::size_t pixels =
            static_cast<std::size_t>(scaledWidth) * scaledHeight;
        std::vector<uint8_t> combinedEvidence(pixels);
        const auto *otEvidence =
            reinterpret_cast<const uint8_t *>(base + readback.otEvidenceOffset);
        const auto *strictEvidence = reinterpret_cast<const uint8_t *>(
            base + readback.strictEvidenceOffset);
        for (std::size_t index = 0; index < pixels; ++index) {
          combinedEvidence[index] =
              replay::combineReplayVisibilityAuditEvidence(
                  otEvidence[index], strictEvidence[index]);
        }

        const replay::ReplayVisibilityAuditRegion visibilityRegion{
            readback.region.nativeX * readback.region.internalScale,
            readback.region.nativeY * readback.region.internalScale,
            scaledWidth, scaledHeight};
        const replay::ReplayVisibilityAuditPlanes visibilityPlanes{
            {base + readback.otOwnerOffset,
             static_cast<std::size_t>(readback.ownerBytes),
             static_cast<std::size_t>(scaledWidth) * sizeof(uint32_t)},
            {base + readback.strictOwnerOffset,
             static_cast<std::size_t>(readback.ownerBytes),
             static_cast<std::size_t>(scaledWidth) * sizeof(uint32_t)},
            {base + readback.otDepthOffset,
             static_cast<std::size_t>(readback.visibilityDepthBytes),
             static_cast<std::size_t>(scaledWidth) * sizeof(float)},
            {base + readback.strictDepthOffset,
             static_cast<std::size_t>(readback.visibilityDepthBytes),
             static_cast<std::size_t>(scaledWidth) * sizeof(float)},
            {combinedEvidence.data(), combinedEvidence.size(), scaledWidth}};
        const replay::ReplayVisibilityAuditReport visibility =
            replay::auditReplayVisibility(visibilityRegion, visibilityPlanes,
                                          readback.visibilityOwners);
        const auto metricValue = [](uint64_t value) {
          return static_cast<int64_t>(std::min<uint64_t>(
              value,
              static_cast<uint64_t>(std::numeric_limits<int64_t>::max())));
        };
        std::optional<replay::ReplayVisibilityStackReport> visibilityStack;
        if (readback.hasVisibilityStack) {
          replay::vulkan_abi::VisibilityStackHeader header{};
          std::memcpy(&header, base + readback.visibilityStackOffset,
                      sizeof(header));
          const bool regionMatches =
              header.atlasRegion[0] == visibilityRegion.atlasX &&
              header.atlasRegion[1] == visibilityRegion.atlasY &&
              header.atlasRegion[2] == visibilityRegion.width &&
              header.atlasRegion[3] == visibilityRegion.height;
          const bool allocationMatches =
              header.recordCapacity == readback.visibilityStackRecordCapacity &&
              readback.visibilityStackBytes ==
                  sizeof(replay::vulkan_abi::VisibilityStackHeader) +
                      static_cast<VkDeviceSize>(
                          readback.visibilityStackRecordCapacity) *
                          sizeof(replay::vulkan_abi::VisibilityStackRecord) &&
              header.overflow <= 1u;
          const uint32_t retainedRecords = std::min(
              header.attemptedRecords, readback.visibilityStackRecordCapacity);
          static_assert(sizeof(replay::ReplayVisibilityStackFragment) ==
                        sizeof(replay::vulkan_abi::VisibilityStackRecord));
          static_assert(alignof(replay::vulkan_abi::VisibilityStackHeader) >=
                        alignof(replay::ReplayVisibilityStackFragment));
          const auto *stackRecords =
              reinterpret_cast<const replay::ReplayVisibilityStackFragment *>(
                  base + readback.visibilityStackOffset + sizeof(header));
          const std::span<const replay::ReplayVisibilityStackFragment>
              fragments(stackRecords, retainedRecords);
          const replay::ReplayVisibilityStackPlanes stackPlanes{
              {base + readback.otOwnerOffset,
               static_cast<std::size_t>(readback.ownerBytes),
               static_cast<std::size_t>(scaledWidth) * sizeof(uint32_t)},
              {base + readback.otDepthOffset,
               static_cast<std::size_t>(readback.visibilityDepthBytes),
               static_cast<std::size_t>(scaledWidth) * sizeof(float)},
              {base + readback.otEvidenceOffset,
               static_cast<std::size_t>(readback.evidenceBytes), scaledWidth}};
          visibilityStack = replay::auditReplayVisibilityStack(
              visibilityRegion, stackPlanes, readback.visibilityOwners,
              regionMatches && allocationMatches ? header.schema : 0u,
              header.attemptedRecords, header.recordCapacity,
              header.overflow != 0u, fragments,
              readback.visibilityStackBarriers);
          const replay::ReplayVisibilityStackReport &stack = *visibilityStack;
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.stack_last_status",
              static_cast<int64_t>(stack.status));
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.stack_last_complete",
              stack.complete() ? 1 : 0);
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.stack_last_attempted_records",
              metricValue(stack.attemptedRecords));
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.stack_last_retained_records",
              metricValue(stack.retainedRecords));
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.stack_last_maximum_distinct_"
              "owners_per_sample",
              stack.maximumDistinctOwnersPerSample);
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.stack_last_occluder_pairs",
              metricValue(stack.occluders.size()));
          ps1::metrics::count(
              "host.renderer.vulkan_visibility.stack_completed");
          if (stack.status == replay::ReplayVisibilityStackStatus::Overflow) {
            ps1::metrics::count(
                "host.renderer.vulkan_visibility.stack_overflow");
          }
          ps1::metrics::traceAtFrame(
              "replay.visibility_stack_audit", readback.guestFrame,
              {{"stack_schema", replay::REPLAY_VISIBILITY_STACK_SCHEMA},
               {"status", static_cast<int64_t>(stack.status)},
               {"complete", stack.complete() ? 1 : 0},
               {"owners", metricValue(readback.visibilityOwners.size())},
               {"atlas_x", stack.region.atlasX},
               {"atlas_y", stack.region.atlasY},
               {"width", stack.region.width},
               {"height", stack.region.height},
               {"attempted_records", metricValue(stack.attemptedRecords)},
               {"record_capacity",
                metricValue(readback.visibilityStackRecordCapacity)},
               {"overflow", header.overflow != 0u ? 1 : 0},
               {"retained_records", metricValue(stack.retainedRecords)},
               {"stale_records", metricValue(stack.staleRecords)},
               {"boundary_records", metricValue(stack.boundaryRecords)},
               {"duplicate_owner_records",
                metricValue(stack.duplicateOwnerRecords)},
               {"inconsistent_duplicate_depth_records",
                metricValue(stack.inconsistentDuplicateDepthRecords)},
               {"ot_evidence_samples", metricValue(stack.otEvidenceSamples)},
               {"complete_owned_samples",
                metricValue(stack.completeOwnedSamples)},
               {"missing_ot_fragment_samples",
                metricValue(stack.missingOtFragmentSamples)},
               {"ot_depth_mismatch_samples",
                metricValue(stack.otDepthMismatchSamples)},
               {"invalid_owner_samples",
                metricValue(stack.invalidOwnerSamples)},
               {"invalid_depth_samples",
                metricValue(stack.invalidDepthSamples)},
               {"occluded_ot_samples", metricValue(stack.occludedOtSamples)},
               {"maximum_distinct_owners_per_sample",
                stack.maximumDistinctOwnersPerSample},
               {"occluder_pairs", metricValue(stack.occluders.size())}});
          for (const replay::ReplayVisibilityStackOccluder &occluder :
               stack.occluders) {
            ps1::metrics::traceAtFrame(
                "replay.visibility_stack_occluder", readback.guestFrame,
                {{"stack_schema", replay::REPLAY_VISIBILITY_STACK_SCHEMA},
                 {"ot_owner", occluder.otOwner},
                 {"physical_owner", occluder.physicalOwner},
                 {"samples", metricValue(occluder.samples)},
                 {"first_atlas_x", occluder.firstAtlasX},
                 {"first_atlas_y", occluder.firstAtlasY},
                 {"minimum_ot_depth_bits",
                  std::bit_cast<uint32_t>(occluder.minimumOtDepth)},
                 {"maximum_ot_depth_bits",
                  std::bit_cast<uint32_t>(occluder.maximumOtDepth)},
                 {"minimum_physical_depth_bits",
                  std::bit_cast<uint32_t>(occluder.minimumPhysicalDepth)},
                 {"maximum_physical_depth_bits",
                  std::bit_cast<uint32_t>(occluder.maximumPhysicalDepth)}});
          }
          fmt::print(
              "[RendererVK] accepted-fragment stack frame {} {}: "
              "records={}/{} overflow={} complete={} owned={} occluded={} "
              "pairs={} max_distinct_owners={}\n",
              readback.guestFrame,
              replay::replayVisibilityStackStatusName(stack.status),
              stack.attemptedRecords, readback.visibilityStackRecordCapacity,
              header.overflow != 0u ? "yes" : "no",
              stack.complete() ? "yes" : "no", stack.completeOwnedSamples,
              stack.occludedOtSamples, stack.occluders.size(),
              stack.maximumDistinctOwnersPerSample);
        }
        ps1::metrics::setState("host.renderer.vulkan_visibility.last_frame",
                               metricValue(readback.guestFrame));
        ps1::metrics::setState("host.renderer.vulkan_visibility.last_status",
                               static_cast<int64_t>(visibility.status));
        ps1::metrics::setState(
            "host.renderer.vulkan_visibility.last_total_samples",
            metricValue(visibility.totalSamples));
        ps1::metrics::setState(
            "host.renderer.vulkan_visibility.last_agreement_samples",
            metricValue(visibility.agreementSamples));
        ps1::metrics::setState(
            "host.renderer.vulkan_visibility.last_background_agreement_samples",
            metricValue(visibility.backgroundAgreementSamples));
        ps1::metrics::setState(
            "host.renderer.vulkan_visibility.last_owned_agreement_samples",
            metricValue(visibility.ownedAgreementSamples));
        ps1::metrics::setState(
            "host.renderer.vulkan_visibility.last_ot_owned_samples",
            metricValue(visibility.otOwnedSamples));
        ps1::metrics::setState(
            "host.renderer.vulkan_visibility.last_depth_owned_samples",
            metricValue(visibility.depthOwnedSamples));
        ps1::metrics::setState(
            "host.renderer.vulkan_visibility.last_conflict_samples",
            metricValue(visibility.confirmedConflictSamples));
        ps1::metrics::setState(
            "host.renderer.vulkan_visibility.last_coverage_divergence_samples",
            metricValue(visibility.coverageDivergenceSamples));
        ps1::metrics::setState(
            "host.renderer.vulkan_visibility.last_indeterminate_samples",
            metricValue(visibility.indeterminateSamples));
        ps1::metrics::setState(
            "host.renderer.vulkan_visibility.last_inconsistent_samples",
            metricValue(visibility.inconsistentEvidenceSamples));
        ps1::metrics::setState(
            "host.renderer.vulkan_visibility.last_conflict_pairs",
            metricValue(visibility.conflicts.size()));
        ps1::metrics::count("host.renderer.vulkan_visibility.completed");
        ps1::metrics::traceAtFrame(
            "replay.visibility_audit", readback.guestFrame,
            {{"status", static_cast<int64_t>(visibility.status)},
             {"owners", metricValue(readback.visibilityOwners.size())},
             {"atlas_x", visibility.region.atlasX},
             {"atlas_y", visibility.region.atlasY},
             {"width", visibility.region.width},
             {"height", visibility.region.height},
             {"samples", metricValue(visibility.totalSamples)},
             {"agreement", metricValue(visibility.agreementSamples)},
             {"background_agreement",
              metricValue(visibility.backgroundAgreementSamples)},
             {"owned_agreement", metricValue(visibility.ownedAgreementSamples)},
             {"ot_owned", metricValue(visibility.otOwnedSamples)},
             {"depth_owned", metricValue(visibility.depthOwnedSamples)},
             {"conflicts", metricValue(visibility.confirmedConflictSamples)},
             {"coverage_divergence",
              metricValue(visibility.coverageDivergenceSamples)},
             {"indeterminate", metricValue(visibility.indeterminateSamples)},
             {"inconsistent",
              metricValue(visibility.inconsistentEvidenceSamples)},
             {"conflict_pairs", metricValue(visibility.conflicts.size())}});

        if (readback.hasVisibilityCandidate) {
          std::vector<uint8_t> candidateEvidence(pixels);
          const auto *liftedEvidence = reinterpret_cast<const uint8_t *>(
              base + readback.liftedEvidenceOffset);
          for (std::size_t index = 0; index < pixels; ++index) {
            candidateEvidence[index] =
                replay::combineReplayVisibilityCandidateEvidence(
                    otEvidence[index], strictEvidence[index],
                    liftedEvidence[index]);
          }
          const std::size_t ownerPitch =
              static_cast<std::size_t>(scaledWidth) * sizeof(uint32_t);
          const std::size_t depthPitch =
              static_cast<std::size_t>(scaledWidth) * sizeof(float);
          const replay::ReplayVisibilityCandidateAuditPlanes candidatePlanes{
              {base + readback.otOwnerOffset,
               static_cast<std::size_t>(readback.ownerBytes), ownerPitch},
              {base + readback.strictOwnerOffset,
               static_cast<std::size_t>(readback.ownerBytes), ownerPitch},
              {base + readback.liftedOwnerOffset,
               static_cast<std::size_t>(readback.ownerBytes), ownerPitch},
              {base + readback.otDepthOffset,
               static_cast<std::size_t>(readback.visibilityDepthBytes),
               depthPitch},
              {base + readback.strictDepthOffset,
               static_cast<std::size_t>(readback.visibilityDepthBytes),
               depthPitch},
              {base + readback.liftedDepthOffset,
               static_cast<std::size_t>(readback.visibilityDepthBytes),
               depthPitch},
              {candidateEvidence.data(), candidateEvidence.size(),
               scaledWidth}};
          const replay::ReplayVisibilityCandidateAuditReport candidate =
              replay::auditReplayVisibilityCandidate(
                  visibilityRegion, candidatePlanes, readback.visibilityOwners);
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.candidate_last_status",
              static_cast<int64_t>(candidate.status));
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.candidate_last_gate_pass",
              candidate.passesRasterGate() ? 1 : 0);
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.candidate_last_baseline_"
              "agreement",
              metricValue(candidate.baselineAgreementSamples));
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.candidate_last_preserved_"
              "agreement",
              metricValue(candidate.agreementPreservedSamples));
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.candidate_last_baseline_"
              "conflicts",
              metricValue(candidate.baselineConflictSamples));
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.candidate_last_resolved",
              metricValue(candidate.conflictResolvedToOtSamples));
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.candidate_last_retained",
              metricValue(candidate.conflictRetainedByStrictSamples));
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.candidate_last_changed_"
              "winner",
              metricValue(candidate.conflictChangedWinnerSamples));
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.candidate_last_regressions",
              metricValue(candidate.candidateRegressionSamples));
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.candidate_last_coverage_"
              "divergence",
              metricValue(candidate.candidateCoverageDivergenceSamples));
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.candidate_last_indeterminate",
              metricValue(candidate.indeterminateSamples));
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.candidate_last_inconsistent",
              metricValue(candidate.inconsistentEvidenceSamples));
          ps1::metrics::count(
              "host.renderer.vulkan_visibility.candidate_completed");
          const int64_t candidateMode =
              replayVisibilityCandidateIdentityRequested ? 1 : 2;
          ps1::metrics::traceAtFrame(
              "replay.visibility_candidate_audit", readback.guestFrame,
              {{"candidate_schema", 2},
               {"candidate_mode", candidateMode},
               {"identity_control",
                replayVisibilityCandidateIdentityRequested ? 1 : 0},
               {"manifest_generation",
                static_cast<int64_t>(
                    replayVisibilityCandidateManifest.generation())},
               {"status", static_cast<int64_t>(candidate.status)},
               {"raster_gate_pass", candidate.passesRasterGate() ? 1 : 0},
               {"samples", metricValue(candidate.totalSamples)},
               {"baseline_agreement",
                metricValue(candidate.baselineAgreementSamples)},
               {"preserved_agreement",
                metricValue(candidate.agreementPreservedSamples)},
               {"baseline_conflicts",
                metricValue(candidate.baselineConflictSamples)},
               {"resolved_to_ot",
                metricValue(candidate.conflictResolvedToOtSamples)},
               {"retained_by_strict",
                metricValue(candidate.conflictRetainedByStrictSamples)},
               {"changed_winner",
                metricValue(candidate.conflictChangedWinnerSamples)},
               {"baseline_coverage_divergence",
                metricValue(candidate.baselineCoverageDivergenceSamples)},
               {"candidate_coverage_divergence",
                metricValue(candidate.candidateCoverageDivergenceSamples)},
               {"regressions",
                metricValue(candidate.candidateRegressionSamples)},
               {"indeterminate", metricValue(candidate.indeterminateSamples)},
               {"inconsistent",
                metricValue(candidate.inconsistentEvidenceSamples)},
               {"conflict_pairs", metricValue(candidate.conflicts.size())}});
          for (const replay::ReplayVisibilityCandidateConflict &conflict :
               candidate.conflicts) {
            ps1::metrics::traceAtFrame(
                "replay.visibility_candidate_conflict", readback.guestFrame,
                {{"candidate_schema", 2},
                 {"candidate_mode", candidateMode},
                 {"identity_control",
                  replayVisibilityCandidateIdentityRequested ? 1 : 0},
                 {"ot_owner", conflict.otOwner},
                 {"strict_owner", conflict.strictOwner},
                 {"samples", metricValue(conflict.samples)},
                 {"resolved_to_ot", metricValue(conflict.resolvedToOtSamples)},
                 {"retained_by_strict",
                  metricValue(conflict.retainedByStrictSamples)},
                 {"changed_winner",
                  metricValue(conflict.changedWinnerSamples)}});
          }
          for (const replay::ReplayVisibilityCandidateOutcome &outcome :
               candidate.outcomes) {
            ps1::metrics::traceAtFrame(
                "replay.visibility_candidate_outcome", readback.guestFrame,
                {{"outcome_schema", 1},
                 {"candidate_mode", candidateMode},
                 {"classification",
                  static_cast<int64_t>(outcome.classification)},
                 {"ot_owner", outcome.otOwner},
                 {"strict_owner", outcome.strictOwner},
                 {"lifted_owner", outcome.liftedOwner},
                 {"samples", metricValue(outcome.samples)},
                 {"first_atlas_x", outcome.firstAtlasX},
                 {"first_atlas_y", outcome.firstAtlasY},
                 {"minimum_ot_depth_bits",
                  std::bit_cast<uint32_t>(outcome.minimumOtDepth)},
                 {"maximum_ot_depth_bits",
                  std::bit_cast<uint32_t>(outcome.maximumOtDepth)},
                 {"minimum_strict_depth_bits",
                  std::bit_cast<uint32_t>(outcome.minimumStrictDepth)},
                 {"maximum_strict_depth_bits",
                  std::bit_cast<uint32_t>(outcome.maximumStrictDepth)},
                 {"minimum_lifted_depth_bits",
                  std::bit_cast<uint32_t>(outcome.minimumLiftedDepth)},
                 {"maximum_lifted_depth_bits",
                  std::bit_cast<uint32_t>(outcome.maximumLiftedDepth)}});
          }
          const char *candidateLabel =
              replayVisibilityCandidateIdentityRequested
                  ? "identity control"
                  : "manifest hypothesis";
          fmt::print("[RendererVK] {} frame {} {}: "
                     "agreement={}/{} conflicts resolved/retained/changed="
                     "{}/{}/{} coverage={} regressions={} unknown={} "
                     "inconsistent={} gate={}\n",
                     candidateLabel, readback.guestFrame,
                     replay::replayVisibilityAuditStatusName(candidate.status),
                     candidate.agreementPreservedSamples,
                     candidate.baselineAgreementSamples,
                     candidate.conflictResolvedToOtSamples,
                     candidate.conflictRetainedByStrictSamples,
                     candidate.conflictChangedWinnerSamples,
                     candidate.candidateCoverageDivergenceSamples,
                     candidate.candidateRegressionSamples,
                     candidate.indeterminateSamples,
                     candidate.inconsistentEvidenceSamples,
                     candidate.passesRasterGate() ? "pass" : "fail");
        }

        // Owner tokens are frame-local. The default compact trace emits every
        // proved-conflict owner. The explicit catalog mode additionally emits
        // every comparable, topology-valid Projected3D owner in this immutable
        // latch so missing conflict geometry cannot masquerade as a separate
        // object. The runtime still derives no key, family count or scale.
        std::vector<uint8_t> conflictOwners(readback.visibilityOwners.size(),
                                            0);
        std::vector<uint64_t> otVisibleSamples(readback.visibilityOwners.size(),
                                               0u);
        std::vector<uint64_t> strictVisibleSamples(
            readback.visibilityOwners.size(), 0u);
        const auto *otOwnerPlane =
            reinterpret_cast<const uint32_t *>(base + readback.otOwnerOffset);
        const auto *strictOwnerPlane = reinterpret_cast<const uint32_t *>(
            base + readback.strictOwnerOffset);
        for (std::size_t sample = 0; sample < pixels; ++sample) {
          const uint32_t otOwner = otOwnerPlane[sample];
          const uint32_t strictOwner = strictOwnerPlane[sample];
          if (otOwner != 0u && otOwner <= otVisibleSamples.size())
            ++otVisibleSamples[otOwner - 1u];
          if (strictOwner != 0u && strictOwner <= strictVisibleSamples.size())
            ++strictVisibleSamples[strictOwner - 1u];
        }
        for (const replay::ReplayVisibilityAuditConflict &conflict :
             visibility.conflicts) {
          if (conflict.otOwner != 0 &&
              conflict.otOwner <= conflictOwners.size())
            conflictOwners[conflict.otOwner - 1u] = 1;
          if (conflict.depthOwner != 0 &&
              conflict.depthOwner <= conflictOwners.size())
            conflictOwners[conflict.depthOwner - 1u] = 1;
        }
        std::vector<uint8_t> tracedOwners = conflictOwners;
        if (visibilityStack.has_value()) {
          for (const replay::ReplayVisibilityStackOccluder &occluder :
               visibilityStack->occluders) {
            if (occluder.otOwner != 0 &&
                occluder.otOwner <= tracedOwners.size()) {
              tracedOwners[occluder.otOwner - 1u] = 1;
            }
            if (occluder.physicalOwner != 0 &&
                occluder.physicalOwner <= tracedOwners.size()) {
              tracedOwners[occluder.physicalOwner - 1u] = 1;
            }
          }
        }
        std::size_t eligibleCatalogOwners = 0;
        if (replayVisibilityCatalogRequested) {
          for (std::size_t ownerIndex = 0;
               ownerIndex < readback.visibilityOwners.size(); ++ownerIndex) {
            const replay::ReplayVisibilityAuditOwner &owner =
                readback.visibilityOwners[ownerIndex];
            if (!owner.comparable() || !owner.provenance.validTopology)
              continue;
            tracedOwners[ownerIndex] = 1;
            ++eligibleCatalogOwners;
          }
          const std::size_t emittedOwners = static_cast<std::size_t>(
              std::count(tracedOwners.begin(), tracedOwners.end(), uint8_t{1}));
          const std::size_t referencedOwners =
              static_cast<std::size_t>(std::count(
                  conflictOwners.begin(), conflictOwners.end(), uint8_t{1}));
          ps1::metrics::traceAtFrame(
              "replay.visibility_catalog", readback.guestFrame,
              {{"catalog_schema", 1},
               {"owner_schema", 3},
               {"owners", metricValue(readback.visibilityOwners.size())},
               {"eligible_owners", metricValue(eligibleCatalogOwners)},
               {"emitted_owners", metricValue(emittedOwners)},
               {"conflict_referenced_owners", metricValue(referencedOwners)}});
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.last_catalog_eligible_owners",
              metricValue(eligibleCatalogOwners));
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.last_catalog_emitted_owners",
              metricValue(emittedOwners));
          ps1::metrics::setState(
              "host.renderer.vulkan_visibility.last_catalog_conflict_owners",
              metricValue(referencedOwners));
          ps1::metrics::count(
              "host.renderer.vulkan_visibility.catalog_completed");
        }
        if (replayPresentedSurfaceCatalogRequested) {
          std::size_t eligibleSurfaceOwners = 0;
          std::size_t eligibleSemiTransparentOwners = 0;
          for (std::size_t ownerIndex = 0;
               ownerIndex < readback.visibilityOwners.size(); ++ownerIndex) {
            const replay::ReplayVisibilityAuditOwner &owner =
                readback.visibilityOwners[ownerIndex];
            if (owner.route != replay::PacketRoute::Projected3D ||
                !owner.fullyPrecise || !owner.authenticDepth ||
                !owner.provenance.validTopology) {
              continue;
            }
            tracedOwners[ownerIndex] = 1;
            ++eligibleSurfaceOwners;
            eligibleSemiTransparentOwners += owner.opaque ? 0u : 1u;
          }
          ps1::metrics::traceAtFrame(
              "replay.presented_surface_catalog", readback.guestFrame,
              {{"catalog_schema", 1},
               {"owner_schema", 3},
               {"owners", metricValue(readback.visibilityOwners.size())},
               {"eligible_surface_owners", metricValue(eligibleSurfaceOwners)},
               {"eligible_semi_transparent_owners",
                metricValue(eligibleSemiTransparentOwners)}});
          ps1::metrics::setState("host.renderer.presented_surface_depth."
                                 "last_catalog_eligible_owners",
                                 metricValue(eligibleSurfaceOwners));
          ps1::metrics::setState(
              "host.renderer.presented_surface_depth."
              "last_catalog_eligible_semi_transparent_owners",
              metricValue(eligibleSemiTransparentOwners));
          ps1::metrics::count(
              "host.renderer.presented_surface_depth.catalog_completed");
        }
        for (std::size_t ownerIndex = 0; ownerIndex < tracedOwners.size();
             ++ownerIndex) {
          if (tracedOwners[ownerIndex] == 0)
            continue;
          traceReplayVisibilityOwner(
              readback.guestFrame, static_cast<uint32_t>(ownerIndex + 1u),
              readback.visibilityOwners[ownerIndex],
              otVisibleSamples[ownerIndex], strictVisibleSamples[ownerIndex]);
        }

        for (const replay::ReplayVisibilityAuditConflict &conflict :
             visibility.conflicts) {
          const replay::ReplayVisibilityAuditOwner &ot =
              readback.visibilityOwners[conflict.otOwner - 1u];
          const replay::ReplayVisibilityAuditOwner &strict =
              readback.visibilityOwners[conflict.depthOwner - 1u];
          ps1::metrics::traceAtFrame(
              "replay.visibility_conflict", readback.guestFrame,
              {{"ot_owner", conflict.otOwner},
               {"depth_owner", conflict.depthOwner},
               {"samples", metricValue(conflict.samples)},
               {"ot_source_ordinal", metricValue(ot.sourceOrdinal)},
               {"depth_source_ordinal", metricValue(strict.sourceOrdinal)},
               {"ot_submission_id", metricValue(ot.submissionId)},
               {"depth_submission_id", metricValue(strict.submissionId)},
               {"ot_frame_index", metricValue(ot.frameIndex)},
               {"depth_frame_index", metricValue(strict.frameIndex)},
               {"ot_operation_index", metricValue(ot.operationIndex)},
               {"depth_operation_index", metricValue(strict.operationIndex)},
               {"ot_triangle_index", ot.triangleIndex},
               {"depth_triangle_index", strict.triangleIndex},
               {"ot_packet_sequence", metricValue(ot.packetSequence)},
               {"depth_packet_sequence", metricValue(strict.packetSequence)},
               {"min_x", conflict.minAtlasX},
               {"min_y", conflict.minAtlasY},
               {"max_x", conflict.maxAtlasX},
               {"max_y", conflict.maxAtlasY},
               {"min_ot_depth_bits",
                std::bit_cast<uint32_t>(conflict.minimumOtDepth)},
               {"max_ot_depth_bits",
                std::bit_cast<uint32_t>(conflict.maximumOtDepth)},
               {"min_strict_depth_bits",
                std::bit_cast<uint32_t>(conflict.minimumStrictDepth)},
               {"max_strict_depth_bits",
                std::bit_cast<uint32_t>(conflict.maximumStrictDepth)}});
        }
        fmt::print(
            "[RendererVK] visibility audit frame {} {}: owners={} "
            "owned={}/{} agreement={} conflicts={} pairs={} divergence={} "
            "unknown={} inconsistent={}\n",
            readback.guestFrame,
            replay::replayVisibilityAuditStatusName(visibility.status),
            readback.visibilityOwners.size(), visibility.otOwnedSamples,
            visibility.depthOwnedSamples, visibility.ownedAgreementSamples,
            visibility.confirmedConflictSamples, visibility.conflicts.size(),
            visibility.coverageDivergenceSamples,
            visibility.indeterminateSamples,
            visibility.inconsistentEvidenceSamples);
      }
      readback.nativeOracle.clear();
      readback.visibilityOwners.clear();
      readback.visibilityStackBarriers.clear();
      readback.hasPreCorrectionDepth = false;
      readback.hasVisibilityAudit = false;
      readback.hasVisibilityCandidate = false;
      readback.hasVisibilityStack = false;
    } catch (const std::exception &error) {
      readback.nativeOracle.clear();
      readback.visibilityOwners.clear();
      readback.visibilityStackBarriers.clear();
      readback.hasPreCorrectionDepth = false;
      readback.hasVisibilityAudit = false;
      readback.hasVisibilityCandidate = false;
      readback.hasVisibilityStack = false;
      disableReplayReadback(error.what());
    }
  }

  void drainReplayDiagnosticReadbacks() {
    if (device == VK_NULL_HANDLE)
      return;
    for (FrameContext &frame : frames) {
      auto &readback = frame.diagnosticReadback;
      if (!readback.pending)
        continue;
      const VkResult waited =
          vkWaitForFences(device, 1, &frame.inFlight, VK_TRUE,
                          std::numeric_limits<uint64_t>::max());
      if (waited != VK_SUCCESS) {
        readback.pending = false;
        readback.nativeOracle.clear();
        readback.visibilityOwners.clear();
        readback.visibilityStackBarriers.clear();
        readback.hasPreCorrectionDepth = false;
        readback.hasVisibilityAudit = false;
        readback.hasVisibilityCandidate = false;
        readback.hasVisibilityStack = false;
        disableReplayReadback(fmt::format("diagnostic fence wait returned {}",
                                          static_cast<int>(waited)));
        continue;
      }
      consumeReplayDiagnosticReadback(frame);
    }
  }

  void drainGpuTimingReport() {
    if (!gpuTimingsEnabled || device == VK_NULL_HANDLE)
      return;
    for (FrameContext &frame : frames) {
      if (!frame.gpuTimingPending)
        continue;
      requireVulkan(vkWaitForFences(device, 1, &frame.inFlight, VK_TRUE,
                                    std::numeric_limits<uint64_t>::max()),
                    "vkWaitForFences(GPU timing drain)");
      consumeGpuTimings(frame);
    }
    reportGpuTimings();
    std::fflush(stdout);
    resetGpuTimingReport();
  }

  void createImageResource(ImageResource &resource, const char *name,
                           VkExtent2D extent, VkFormat format,
                           VkImageUsageFlags usage,
                           VkFormatFeatureFlags requiredFeatures,
                           VkImageAspectFlags aspectMask) {
    if (resource.image != VK_NULL_HANDLE || resource.memory != VK_NULL_HANDLE ||
        resource.view != VK_NULL_HANDLE) {
      throw std::runtime_error(
          fmt::format("{} Vulkan resource already exists", name));
    }
    requireImageSupport(name, extent, format, usage, requiredFeatures);

    ImageResource candidate;
    candidate.extent = extent;
    candidate.format = format;
    try {
      createImage(extent.width, extent.height, format, usage, candidate.image,
                  candidate.memory);
      candidate.view = createImageView(candidate.image, format, aspectMask);
    } catch (...) {
      destroyImageResource(candidate);
      throw;
    }
    resource = candidate;
  }

  VkSampler createSampler(VkFilter filter) const {
    VkSamplerCreateInfo samplerInfo{VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO};
    samplerInfo.magFilter = filter;
    samplerInfo.minFilter = filter;
    samplerInfo.mipmapMode = VK_SAMPLER_MIPMAP_MODE_NEAREST;
    samplerInfo.addressModeU = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
    samplerInfo.addressModeV = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
    samplerInfo.addressModeW = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_EDGE;
    samplerInfo.maxAnisotropy = 1.0f;
    samplerInfo.minLod = 0.0f;
    samplerInfo.maxLod = 0.0f;
    VkSampler sampler = VK_NULL_HANDLE;
    requireVulkan(vkCreateSampler(device, &samplerInfo, nullptr, &sampler),
                  "vkCreateSampler");
    return sampler;
  }

  static std::string_view gpuTimingPointName(GpuTimingPoint point) noexcept {
    switch (point) {
    case GpuTimingPoint::CommandBegin:
      return "command_begin";
    case GpuTimingPoint::SetupEnd:
      return "setup";
    case GpuTimingPoint::MidpointReplayEnd:
      return "midpoint_replay";
    case GpuTimingPoint::MidpointResolveEnd:
      return "midpoint_resolve";
    case GpuTimingPoint::InterpolationRestoreEnd:
      return "interpolation_restore";
    case GpuTimingPoint::ReplayEnd:
      return "replay_tail";
    case GpuTimingPoint::ResolveEnd:
      return "resolve";
    case GpuTimingPoint::PresentEnd:
      return "present";
    }
    return "unknown";
  }

  uint64_t gpuTimestampDelta(uint64_t begin, uint64_t end) const noexcept {
    if (graphicsTimestampValidBits >= 64u)
      return end - begin;
    const uint64_t mask =
        (UINT64_C(1) << graphicsTimestampValidBits) - UINT64_C(1);
    return (end - begin) & mask;
  }

  uint64_t gpuTimestampNanoseconds(uint64_t ticks) const noexcept {
    const long double nanoseconds =
        static_cast<long double>(ticks) * gpuTimestampPeriodNanoseconds;
    if (nanoseconds >=
        static_cast<long double>(std::numeric_limits<uint64_t>::max())) {
      return std::numeric_limits<uint64_t>::max();
    }
    return static_cast<uint64_t>(nanoseconds + 0.5L);
  }

  void consumeGpuTimings(FrameContext &frame) {
    if (!frame.gpuTimingPending || frame.gpuTimingQueryPool == VK_NULL_HANDLE)
      return;
    frame.gpuTimingPending = false;
    if (frame.gpuTimingPointCount < 2u)
      return;
    std::array<uint64_t, kMaxGpuTimingPoints> timestamps{};
    const VkResult result = vkGetQueryPoolResults(
        device, frame.gpuTimingQueryPool, 0u, frame.gpuTimingPointCount,
        sizeof(uint64_t) * frame.gpuTimingPointCount, timestamps.data(),
        sizeof(uint64_t), VK_QUERY_RESULT_64_BIT);
    if (result != VK_SUCCESS) {
      ps1::metrics::count("host.renderer.vulkan_gpu_timing.query_failure");
      return;
    }
    for (uint32_t index = 1u; index < frame.gpuTimingPointCount; ++index) {
      const uint64_t elapsedNanoseconds = gpuTimestampNanoseconds(
          gpuTimestampDelta(timestamps[index - 1u], timestamps[index]));
      const std::string_view name =
          gpuTimingPointName(frame.gpuTimingPoints[index]);
      const std::size_t pointIndex =
          static_cast<std::size_t>(frame.gpuTimingPoints[index]);
      gpuTimingNanoseconds[pointIndex] += elapsedNanoseconds;
      ++gpuTimingSamples[pointIndex];
      ps1::metrics::count(fmt::format("host.renderer.vulkan_gpu.{}_ns", name),
                          elapsedNanoseconds);
      ps1::metrics::count(
          fmt::format("host.renderer.vulkan_gpu.{}_samples", name));
    }
    const uint64_t totalNanoseconds = gpuTimestampNanoseconds(gpuTimestampDelta(
        timestamps[0], timestamps[frame.gpuTimingPointCount - 1u]));
    ps1::metrics::count("host.renderer.vulkan_gpu.total_ns", totalNanoseconds);
    ps1::metrics::count("host.renderer.vulkan_gpu.total_samples");
    gpuTimingTotalNanoseconds += totalNanoseconds;
    ++gpuTimingTotalSamples;
  }

  void resetGpuTimingReport() noexcept {
    gpuTimingNanoseconds.fill(0u);
    gpuTimingSamples.fill(0u);
    gpuTimingTotalNanoseconds = 0u;
    gpuTimingTotalSamples = 0u;
  }

  void reportGpuTimings() const {
    if (!gpuTimingsEnabled || gpuTimingTotalSamples == 0u)
      return;
    const double totalMilliseconds =
        static_cast<double>(gpuTimingTotalNanoseconds) / 1'000'000.0;
    const double averageMilliseconds =
        totalMilliseconds / static_cast<double>(gpuTimingTotalSamples);
    fmt::print("[RendererVK] GPU timing total: {:.3f} ms / {} submissions "
               "({:.3f} ms average)\n",
               totalMilliseconds, gpuTimingTotalSamples, averageMilliseconds);
    for (std::size_t index = 1u; index < gpuTimingSamples.size(); ++index) {
      if (gpuTimingSamples[index] == 0u)
        continue;
      const double milliseconds =
          static_cast<double>(gpuTimingNanoseconds[index]) / 1'000'000.0;
      fmt::print("[RendererVK] GPU timing {}: {:.3f} ms / {} samples "
                 "({:.3f} ms average)\n",
                 gpuTimingPointName(static_cast<GpuTimingPoint>(index)),
                 milliseconds, gpuTimingSamples[index],
                 milliseconds / static_cast<double>(gpuTimingSamples[index]));
    }
  }

  void beginGpuTimings(FrameContext &frame) {
    frame.gpuTimingPointCount = 0u;
    if (!gpuTimingsEnabled)
      return;
    vkCmdResetQueryPool(frame.commandBuffer, frame.gpuTimingQueryPool, 0u,
                        kMaxGpuTimingPoints);
    frame.gpuTimingPoints[0] = GpuTimingPoint::CommandBegin;
    frame.gpuTimingPointCount = 1u;
    vkCmdWriteTimestamp(frame.commandBuffer, VK_PIPELINE_STAGE_TOP_OF_PIPE_BIT,
                        frame.gpuTimingQueryPool, 0u);
  }

  void writeGpuTiming(FrameContext &frame, GpuTimingPoint point) {
    if (!gpuTimingsEnabled)
      return;
    if (frame.gpuTimingPointCount >= kMaxGpuTimingPoints)
      throw std::runtime_error("Vulkan GPU timing point capacity exceeded");
    const uint32_t query = frame.gpuTimingPointCount++;
    frame.gpuTimingPoints[query] = point;
    vkCmdWriteTimestamp(frame.commandBuffer,
                        VK_PIPELINE_STAGE_BOTTOM_OF_PIPE_BIT,
                        frame.gpuTimingQueryPool, query);
  }

  void createCommandResources() {
    VkCommandPoolCreateInfo poolInfo{
        VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO};
    poolInfo.flags = VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT;
    poolInfo.queueFamilyIndex = graphicsFamily;
    requireVulkan(vkCreateCommandPool(device, &poolInfo, nullptr, &commandPool),
                  "vkCreateCommandPool");

    std::array<VkCommandBuffer, kFramesInFlight> commandBuffers{};
    VkCommandBufferAllocateInfo allocate{
        VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO};
    allocate.commandPool = commandPool;
    allocate.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;
    allocate.commandBufferCount = kFramesInFlight;
    requireVulkan(
        vkAllocateCommandBuffers(device, &allocate, commandBuffers.data()),
        "vkAllocateCommandBuffers");

    constexpr VkDeviceSize stagingSize =
        static_cast<VkDeviceSize>(GPU::VRAM_WIDTH) * GPU::VRAM_HEIGHT *
        sizeof(Color16);
    for (uint32_t i = 0; i < kFramesInFlight; ++i) {
      FrameContext &frame = frames[i];
      frame.commandBuffer = commandBuffers[i];
      createBuffer(stagingSize, VK_BUFFER_USAGE_TRANSFER_SRC_BIT,
                   VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT |
                       VK_MEMORY_PROPERTY_HOST_COHERENT_BIT,
                   frame.stagingBuffer, frame.stagingMemory);
      requireVulkan(vkMapMemory(device, frame.stagingMemory, 0, stagingSize, 0,
                                &frame.stagingMapped),
                    "vkMapMemory");

      VkSemaphoreCreateInfo semaphoreInfo{
          VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO};
      requireVulkan(vkCreateSemaphore(device, &semaphoreInfo, nullptr,
                                      &frame.imageAvailable),
                    "vkCreateSemaphore(acquire)");
      VkFenceCreateInfo fenceInfo{VK_STRUCTURE_TYPE_FENCE_CREATE_INFO};
      fenceInfo.flags = VK_FENCE_CREATE_SIGNALED_BIT;
      requireVulkan(vkCreateFence(device, &fenceInfo, nullptr, &frame.inFlight),
                    "vkCreateFence");
      if (gpuTimingsEnabled) {
        VkQueryPoolCreateInfo queryInfo{
            VK_STRUCTURE_TYPE_QUERY_POOL_CREATE_INFO};
        queryInfo.queryType = VK_QUERY_TYPE_TIMESTAMP;
        queryInfo.queryCount = kMaxGpuTimingPoints;
        requireVulkan(vkCreateQueryPool(device, &queryInfo, nullptr,
                                        &frame.gpuTimingQueryPool),
                      "vkCreateQueryPool(GPU timings)");
      }
    }
  }

  void createDescriptors() {
    VkDescriptorSetLayoutBinding binding{};
    binding.binding = 0;
    binding.descriptorType = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
    binding.descriptorCount = 1;
    binding.stageFlags = VK_SHADER_STAGE_FRAGMENT_BIT;
    VkDescriptorSetLayoutCreateInfo layoutInfo{
        VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO};
    layoutInfo.bindingCount = 1;
    layoutInfo.pBindings = &binding;
    requireVulkan(vkCreateDescriptorSetLayout(device, &layoutInfo, nullptr,
                                              &sampledImageLayout),
                  "vkCreateDescriptorSetLayout");

    VkDescriptorPoolSize poolSize{};
    poolSize.type = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
    poolSize.descriptorCount = 7;
    VkDescriptorPoolCreateInfo poolInfo{
        VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO};
    poolInfo.maxSets = 7;
    poolInfo.poolSizeCount = 1;
    poolInfo.pPoolSizes = &poolSize;
    requireVulkan(
        vkCreateDescriptorPool(device, &poolInfo, nullptr, &descriptorPool),
        "vkCreateDescriptorPool");
    std::array<VkDescriptorSetLayout, 7> layouts{
        sampledImageLayout, sampledImageLayout, sampledImageLayout,
        sampledImageLayout, sampledImageLayout, sampledImageLayout,
        sampledImageLayout};
    VkDescriptorSetAllocateInfo allocate{
        VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO};
    allocate.descriptorPool = descriptorPool;
    allocate.descriptorSetCount = static_cast<uint32_t>(layouts.size());
    allocate.pSetLayouts = layouts.data();
    std::array<VkDescriptorSet, 7> sets{};
    requireVulkan(vkAllocateDescriptorSets(device, &allocate, sets.data()),
                  "vkAllocateDescriptorSets");
    nativeSnapshotDescriptor = sets[0];
    scanoutDescriptor = sets[1];
    replayAtlasDescriptor = sets[2];
    replayDepthDescriptor = sets[3];
    replayPreCorrectionDepthDescriptor = sets[4];
    replayInterpolationPriorColorDescriptor = sets[5];
    replayInterpolationPriorDepthDescriptor = sets[6];

    VkPushConstantRange pushRange{};
    pushRange.stageFlags = VK_SHADER_STAGE_FRAGMENT_BIT;
    pushRange.offset = 0;
    pushRange.size = sizeof(VulkanScanoutPushConstants);
    VkPipelineLayoutCreateInfo nativeLayoutInfo{
        VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO};
    nativeLayoutInfo.setLayoutCount = 1;
    nativeLayoutInfo.pSetLayouts = &sampledImageLayout;
    nativeLayoutInfo.pushConstantRangeCount = 1;
    nativeLayoutInfo.pPushConstantRanges = &pushRange;
    requireVulkan(vkCreatePipelineLayout(device, &nativeLayoutInfo, nullptr,
                                         &nativeSnapshotPipelineLayout),
                  "vkCreatePipelineLayout(native)");

    std::array<VkDescriptorSetLayout, 4> temporalLayouts{
        sampledImageLayout, sampledImageLayout, sampledImageLayout,
        sampledImageLayout};
    VkPipelineLayoutCreateInfo temporalLayoutInfo = nativeLayoutInfo;
    VkPushConstantRange temporalPushRange = pushRange;
    temporalPushRange.size = sizeof(VulkanTemporalScanoutPushConstants);
    temporalLayoutInfo.setLayoutCount =
        static_cast<uint32_t>(temporalLayouts.size());
    temporalLayoutInfo.pSetLayouts = temporalLayouts.data();
    temporalLayoutInfo.pPushConstantRanges = &temporalPushRange;
    requireVulkan(vkCreatePipelineLayout(device, &temporalLayoutInfo, nullptr,
                                         &replayTemporalResolvePipelineLayout),
                  "vkCreatePipelineLayout(replay temporal resolve)");

    VkPipelineLayoutCreateInfo presentLayoutInfo{
        VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO};
    presentLayoutInfo.setLayoutCount = 1;
    presentLayoutInfo.pSetLayouts = &sampledImageLayout;
    requireVulkan(vkCreatePipelineLayout(device, &presentLayoutInfo, nullptr,
                                         &presentPipelineLayout),
                  "vkCreatePipelineLayout(present)");
  }

  void
  updateSampledDescriptor(VkDescriptorSet set, VkImageView view,
                          VkSampler sampler,
                          VkImageLayout imageLayout =
                              VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL) const {
    VkDescriptorImageInfo imageInfo{};
    imageInfo.sampler = sampler;
    imageInfo.imageView = view;
    imageInfo.imageLayout = imageLayout;
    VkWriteDescriptorSet write{VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};
    write.dstSet = set;
    write.dstBinding = 0;
    write.descriptorCount = 1;
    write.descriptorType = VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;
    write.pImageInfo = &imageInfo;
    vkUpdateDescriptorSets(device, 1, &write, 0, nullptr);
  }

  void createNativeSnapshotResources() {
    createImage(GPU::VRAM_WIDTH, GPU::VRAM_HEIGHT, kNativeSnapshotFormat,
                VK_IMAGE_USAGE_TRANSFER_DST_BIT | VK_IMAGE_USAGE_SAMPLED_BIT,
                nativeSnapshotImage, nativeSnapshotMemory);
    nativeSnapshotView =
        createImageView(nativeSnapshotImage, kNativeSnapshotFormat);
    nativeSnapshotSampler = createSampler(VK_FILTER_NEAREST);
    updateSampledDescriptor(nativeSnapshotDescriptor, nativeSnapshotView,
                            nativeSnapshotSampler);
  }

  void destroyReplayResources(ReplayResources &resources) {
    if (device != VK_NULL_HANDLE) {
      if (resources.seedPipeline != VK_NULL_HANDLE)
        vkDestroyPipeline(device, resources.seedPipeline, nullptr);
      if (resources.seedFramebuffer != VK_NULL_HANDLE)
        vkDestroyFramebuffer(device, resources.seedFramebuffer, nullptr);
      if (resources.seedRenderPass != VK_NULL_HANDLE)
        vkDestroyRenderPass(device, resources.seedRenderPass, nullptr);
      if (resources.seedPipelineLayout != VK_NULL_HANDLE)
        vkDestroyPipelineLayout(device, resources.seedPipelineLayout, nullptr);
      if (resources.descriptorPool != VK_NULL_HANDLE)
        vkDestroyDescriptorPool(device, resources.descriptorPool, nullptr);
      if (resources.descriptorSetLayout != VK_NULL_HANDLE) {
        vkDestroyDescriptorSetLayout(device, resources.descriptorSetLayout,
                                     nullptr);
      }
      if (resources.nativeShadowSampler != VK_NULL_HANDLE)
        vkDestroySampler(device, resources.nativeShadowSampler, nullptr);
    }
    destroyImageResource(resources.depth);
    destroyImageResource(resources.surfaceDepth);
    destroyImageResource(resources.mask);
    destroyImageResource(resources.color);
    destroyImageResource(resources.nativeShadow);
    resources = {};
  }

  void destroyReplayResources() { destroyReplayResources(replayResources); }

